/* Contenu de révision. Pour ajouter une question : copier une ligne {q, o, e} dans le bon thème.
   La bonne réponse est TOUJOURS la première option de o ; l ordre est mélangé à l affichage.
   l:"spp av" limite une question à certains objectifs (fi, spp, av). */
/* ---------- Référentiels ---------- */
const LV = {fi:"SPV / FI", spp:"Concours SPP", av:"Avancement", tous:"Tous niveaux"};
const TH = {
  suap:{n:"Secours à personne",k:"SUAP"}, inc:{n:"Incendie",k:"INC"}, div:{n:"Opérations diverses",k:"DIV"},
  sr:{n:"Secours routier",k:"SR"}, fdf:{n:"Feux de forêt",k:"FDF"}, cult:{n:"Culture & matériel",k:"CULT"},
  com:{n:"Commandement",k:"COM"}, fr:{n:"Français",k:"FR"}, math:{n:"Mathématiques",k:"MATH"}
};

/* ---------- QCM (la bonne réponse est toujours la 1re option ; l'ordre est mélangé à l'affichage) ---------- */
const QDATA = {
suap:[
 {q:"Chez l'adulte, à quelle fréquence réalise-t-on les compressions thoraciques ?",o:["100 à 120 par minute","60 à 80 par minute","80 à 100 par minute","Plus de 140 par minute"],e:"100 à 120 compressions par minute, en laissant le thorax revenir complètement entre chaque compression."},
 {q:"Quelle profondeur de compression thoracique vise-t-on chez l'adulte ?",o:["5 à 6 cm","2 à 3 cm","3 à 4 cm","8 à 10 cm"],e:"5 à 6 cm, au centre de la poitrine, bras tendus."},
 {q:"Chez l'adulte en arrêt cardiaque, quel est le rapport compressions / insufflations ?",o:["30 / 2","15 / 2","30 / 5","5 / 1"],e:"30 compressions puis 2 insufflations, en limitant au maximum les interruptions."},
 {q:"Une victime est inconsciente et respire normalement. Que fais-tu ?",o:["Je la mets en PLS et je surveille sa respiration","Je commence la RCP","Je la laisse sur le dos jambes surélevées","Je la mets en position assise"],e:"La PLS garde les voies aériennes libres. Si la respiration s'arrête, on remet la victime sur le dos et on débute la RCP."},
 {q:"Sur un membre, la compression directe d'une hémorragie externe est inefficace. Quel geste suit ?",o:["Poser un garrot","Surélever le membre et attendre","Faire un point de compression à distance","Retirer le pansement pour mieux voir"],e:"Garrot quand la compression directe est inefficace ou impossible sur un membre. On note l'heure de pose."},
 {q:"Un adulte conscient s'étouffe et ne peut ni parler ni tousser. Que fais-tu en premier ?",o:["1 à 5 claques dans le dos","Des compressions thoraciques au sol","Je lui donne à boire","Je l'allonge en PLS"],e:"Obstruction totale : 1 à 5 claques dans le dos, puis 1 à 5 compressions abdominales si elles sont inefficaces, en alternance."},
 {q:"Brûlure thermique récente : quel refroidissement ?",o:["Eau courante tempérée pendant environ 10 minutes","Glace directement sur la brûlure","Pommade grasse puis pansement","Eau glacée pendant 1 heure"],e:"Refroidir le plus tôt possible à l'eau tempérée (15 à 25 °C) environ 10 minutes. Attention à l'hypothermie chez l'enfant et sur les grandes surfaces."},
 {q:"Entre quelles valeurs est coté le score de Glasgow ?",o:["3 et 15","0 et 10","1 et 20","0 et 15"],e:"Yeux (4) + verbal (5) + moteur (6) : de 3 à 15."},
 {q:"Dans quel ordre réalise-t-on les bilans ?",o:["Circonstanciel, urgence vitale, complémentaire, surveillance","Urgence vitale, circonstanciel, surveillance, complémentaire","Complémentaire, circonstanciel, urgence vitale, surveillance","Surveillance, urgence vitale, complémentaire, circonstanciel"],e:"Le bilan circonstanciel (sécurité, contexte, nombre de victimes) précède le bilan d'urgence vitale, puis viennent le bilan complémentaire et la surveillance."},
 {q:"Quelle est la fréquence respiratoire normale d'un adulte au repos ?",o:["12 à 20 mouvements par minute","6 à 10 par minute","25 à 35 par minute","40 à 60 par minute"],e:"12 à 20 mouvements par minute chez l'adulte."},
 {q:"Pendant l'analyse du défibrillateur (DAE) :",o:["Personne ne touche la victime","On continue les compressions","On fait les insufflations","On retire les électrodes"],e:"Tout contact peut fausser l'analyse. On reprend la RCP aussitôt après le choc, ou si le choc n'est pas indiqué."},
 {q:"Pourquoi noter l'heure de début des signes d'un AVC ?",o:["Elle conditionne l'accès aux traitements en filière spécialisée","Pour le rapport administratif uniquement","Pour calculer le score de Glasgow","Elle n'a pas d'importance"],e:"Les traitements de l'AVC dépendent du délai écoulé. Signes d'alerte : visage déformé, faiblesse d'un bras, trouble de la parole."},
 {q:"Un diabétique est conscient, confus, en sueur, et peut avaler. Que fais-tu ?",o:["Je lui donne du sucre et je transmets le bilan","Je lui fais une injection d'insuline","Je le laisse dormir","Je ne lui donne rien par la bouche"],e:"Signes évocateurs d'hypoglycémie : sucre s'il est conscient et capable d'avaler, puis bilan et avis médical."},
 {q:"Quel est le danger du monoxyde de carbone (CO) ?",o:["Gaz incolore et inodore qui empêche le sang de transporter l'oxygène","Gaz irritant à forte odeur","Gaz inflammable sans aucune toxicité","Gaz qui ne se trouve qu'en extérieur"],e:"Le CO se fixe sur l'hémoglobine. Maux de tête et nausées chez plusieurs personnes d'un même lieu doivent alerter."},
 {q:"Qu'est-ce que le prompt secours ?",o:["Une action d'équipe pour prendre en charge sans délai les détresses vitales et les urgences fonctionnelles","Un transport sanitaire sans médecin","Une intervention réalisée par un seul pompier","Un appel au 15 par un témoin"],e:"Son intérêt est son caractère réflexe (GDO Secours et soins d'urgence aux personnes, 2022)."},
 {q:"Qu'est-ce qu'une carence ambulancière ?",o:["Un transport prescrit par le SAMU faute de transporteur sanitaire privé disponible","Un refus de soins de la victime","Une panne de VSAV","Une intervention sans victime"],e:"Elle exige la même qualité de prise en charge qu'une mission de SSUAP. L'établissement siège du SAMU la prend en charge financièrement (GDO SSUAP 2022)."},
 {q:"Une opération avec au moins une victime : la régulation médicale est…",o:["Systématique et assurée par le CRRA du SAMU","Facultative, à la demande du chef d'agrès","Réservée aux urgences vitales","Assurée par le CTA-CODIS"],e:"La régulation médicale est systématique et incombe au CRRA 15. Quand le 15 demande des moyens, le CTA-CODIS reste décisionnaire de leur engagement (GDO SSUAP 2022)."},
 {q:"Le secret professionnel sur l'état de santé d'une victime :",o:["Ne s'éteint pas avec son décès","Cesse dès sa mort","Peut être partagé avec les forces de l'ordre","Ne concerne que les médecins"],e:"Il couvre tout ce qui a été vu, entendu ou supposé. Le secret médical ne se partage pas avec les forces de l'ordre, et sa violation est un délit (GDO SSUAP 2022)."},
 {q:"Un adulte lucide refuse d'être transporté. Que fais-tu ?",o:["Je fais signer une décharge et je lui en laisse un double","Je l'emmène de force","Je pars sans rien noter","J'appelle la police pour l'obliger"],e:"Une victime majeure en pleine possession de ses capacités peut refuser. On matérialise ce refus par une décharge signée et on lui en laisse un double (GDO SSUAP 2022)."},
 {q:"Un mineur peut-il refuser d'être pris en charge ou hospitalisé ?",o:["Non","Oui, à partir de 15 ans","Oui, s'il signe une décharge","Oui, si ses parents sont absents"],e:"Un mineur non émancipé ne peut pas refuser. La croyance religieuse des parents ne justifie pas non plus un refus de soins pour l'enfant (GDO SSUAP 2022)."},
 {q:"Mineur seul, sans besoin d'évacuation. À qui le confier ?",o:["Au représentant légal, aux forces de l'ordre ou à un adulte qui en a la garde","À un passant volontaire","Le laisser seul s'il va bien","Le ramener à la caserne"],e:"Sans représentant légal, le mineur est sous la protection et la responsabilité des sapeurs-pompiers (GDO SSUAP 2022)."},
 {q:"Piqûre avec une aiguille souillée, sans protocole AES local. Que fais-tu ?",o:["Laver à l'eau et au savon puis désinfecter 5 minutes minimum (Dakin, eau de Javel diluée)","Faire saigner puis mettre un pansement","Désinfecter à l'alcool 10 secondes","Attendre la fin de l'intervention"],e:"Lavage eau et savon, puis désinfection 5 min minimum. En cas de projection sur une muqueuse : rinçage abondant au sérum physiologique, ou à l'eau (GDO SSUAP 2022)."},
 {q:"Quelles sont les trois zones du zonage opérationnel ?",o:["Exclusion (rouge), contrôlée (orange), soutien (verte)","Chaude, tiède, froide","Danger, alerte, repos","Avant, centre, arrière"],e:"Les limites extérieures de la zone de soutien forment le périmètre de sécurité (GDO SSUAP 2022)."},
 {q:"Nombreuses victimes : comment les premiers intervenants classent-ils les blessés ?",o:["En état grave (EG) ou état léger (EL)","En UA et UR","Par ordre d'arrivée","Par âge"],e:"La catégorisation EG/EL est secouriste. Le classement UA/UR relève du tri médical, et seulement dans le cadre d'un plan NOVI (GDO SSUAP 2022)."},
 {q:"Nombreuses victimes : où regroupe-t-on les impliqués (valides, pas ou peu blessés) ?",o:["Dans un lieu différent de celui des blessés graves","Avec les blessés graves","Dans les VSAV","On les laisse partir"],e:"Les impliqués sont regroupés à part. Un dispositif de repérage (fiches, bracelets) permet de les identifier et de les suivre (GDO SSUAP 2022)."},
 {q:"Que permet le système SINUS ?",o:["Dénombrer, identifier et suivre les victimes en situation NOVI","Géolocaliser les VSAV","Transmettre un ECG","Réserver un lit à l'hôpital"],e:"SINUS (Système d'Information Numérique Standardisé) sert au dénombrement et au suivi des nombreuses victimes (GDO SSUAP 2022)."},
 {q:"Qu'est-ce qu'une urgence vitale ?",o:["Une situation où la vie est en danger imminent, avec risque de décès sans soins rapides et adaptés","Toute douleur importante","Une victime qui saigne","Un malaise chez une personne âgée"],e:"C'est la définition du GDO SSUAP (2022)."},
 {q:"Quelle est la première cause d'accidents liés à l'activité SSUAP chez les pompiers ?",o:["Les troubles musculo-squelettiques (port de charges, postures)","Les accidents de la route","Les agressions","Les piqûres"],e:"Les TMS viennent du port de charges lourdes et des postures inconfortables ou maintenues longtemps (GDO SSUAP 2022)."},
 {q:"Situation tendue ou menace d'agression en intervention. Quelle conduite ?",o:["Conditionner vite la victime pour faire le bilan à l'abri, sacs utilisables comme boucliers","Faire le bilan sur place quoi qu'il arrive","Répondre aux provocations","Laisser la victime et repartir sans prévenir"],e:"On peut se servir des sacs de prompt secours comme boucliers, et on met la victime à l'abri au plus vite pour faire le bilan (GDO SSUAP 2022)."},
 {q:"Une équipe engagée doit-elle pouvoir prendre en charge le malaise d'un de ses membres sans attendre un moyen SSUAP dédié ?",o:["Oui, de manière autonome en toute circonstance","Non, c'est le rôle exclusif du SSSM","Seulement si un infirmier est présent","Seulement en feu de forêt"],e:"Une équipe engagée doit faire face à la blessure ou au malaise de l'un des siens de manière autonome (GDO Préparation et soutien de l'intervenant)"},
 {q:"En dessous de quelle température ambiante la vigilance au froid s'impose-t-elle ?",o:["5 °C","0 °C","10 °C","-5 °C"],e:"Dès que la température (à l'abri du vent) est inférieure à 5 °C, l'exposition au froid a des effets directs sur la santé (GDO Préparation et soutien de l'intervenant)"},
 {q:"Quelle durée d'autonomie en eau et nourriture une colonne de renfort doit-elle avoir ?",o:["24 heures","12 heures","48 heures","6 heures"],e:"La colonne doit disposer d'eau et de nourriture pour 24 heures (GDO Préparation et soutien de l'intervenant)"},
 {q:"Quand faut-il demander les relèves ?",o:["Par anticipation, avant de constater la fatigue des personnels","Quand les personnels sont épuisés","À la fin de l'intervention","Uniquement après un accident"],e:"Ce n'est pas lorsque l'on constate la fatigue que les relèves doivent être demandées (GDO Préparation et soutien de l'intervenant)"},
 {q:"Quel indice croise température et humidité pour évaluer le risque de coup de chaleur ?",o:["L'indice de chaleur (heat index)","L'indice IFM","L'indice UV","Le facteur de chute"],e:"Le croisement température à l'ombre / humidité relative donne un niveau de risque ; ajouter 15 en plein soleil (GDO Préparation et soutien de l'intervenant)"},
 {q:"Quelle contenance de bouteille d'eau est préconisée pour l'hydratation des intervenants ?",o:["0,5 L","1,5 L","5 L","0,25 L"],e:"Des bouteilles de 0,5 L de préférence, pour éviter le gâchis et pour l'hygiène, idéalement d'eau minérale (GDO Préparation et soutien de l'intervenant)"},
 {q:"Un SP passé par la zone de soins est-il automatiquement compté comme blessé ?",o:["Non","Oui, toujours","Oui, s'il y reste plus de 10 minutes","Oui, s'il a bu de l'eau"],e:"Passer par la zone de soins ne doit pas faire systématiquement comptabiliser le SP comme malade ou blessé (GDO Préparation et soutien de l'intervenant)"},
 {q:"Combien de temps environ dure le repos en zone de réhabilitation avant de repartir après un bilan ?",o:["Une trentaine de minutes","5 minutes","2 heures","Une nuit complète"],e:"Après une trentaine de minutes de repos et un rapide bilan secouriste, il récupère ses EPI pour repartir (GDO Préparation et soutien de l'intervenant)"},
 {q:"Quel niveau d'activité physique minimum recommande le PNNS ?",o:["30 min de marche rapide par jour, au moins 5 jours par semaine","10 min par jour, 3 jours par semaine","1 heure par semaine","2 heures par jour, tous les jours"],e:"Le PNNS préconise au moins 30 minutes de marche rapide par jour, au moins 5 jours/semaine (GDO Préparation et soutien de l'intervenant)"},
 {q:"La mission de soutien sanitaire en opération est-elle cumulable avec d'autres missions ?",o:["Non, elle doit être exclusive pour les personnels qui en sont chargés","Oui, avec l'attaque du feu","Oui, avec la conduite des engins","Oui, avec le commandement"],e:"La mission de soutien sanitaire doit être exclusive pour les personnels qui en sont chargés (GDO Préparation et soutien de l'intervenant)"},
 {q:"Quelle part de l'activité opérationnelle des SIS représentait le SSUAP en 2020 ?",o:["Environ 71 %","Environ 25 %","Environ 50 %","Environ 95 %"],e:"3,61 millions d'interventions en 2020, soit 71 % de l'activité opérationnelle (GDO Secours et soins d'urgence aux personnes 2022)"},
 {q:"Dans quel cadre utilise-t-on le classement UA / UR ?",o:["Uniquement dans un plan NOVI","Sur toute intervention SSUAP","Uniquement pour les malaises","Pour classer les appels au CTA"],e:"Le classement urgence absolue / urgence relative est utilisé uniquement dans le cadre d'un plan NOVI (GDO Secours et soins d'urgence aux personnes 2022)"},
 {q:"Qui détermine l'établissement de destination d'une victime ?",o:["La régulation médicale du SAMU, en tenant compte du choix de la victime","Le chef d'agrès seul","Le conducteur du VSAV","La famille de la victime"],e:"La destination la plus adaptée est déterminée par la régulation médicale du SAMU, en tenant compte du choix de la victime (GDO Secours et soins d'urgence aux personnes 2022)"},
 {q:"La victime peut exprimer un choix d'hôpital. Que fait le chef d'agrès ?",o:["Il le recueille et le transmet au médecin régulateur avec son bilan","Il l'ignore","Il l'y conduit directement sans régulation","Il demande l'avis de la police"],e:"Le chef d'agrès recueille le choix de l'établissement et le transmet au médecin régulateur en même temps que le bilan (GDO Secours et soins d'urgence aux personnes 2022)"},
 {q:"L'état de la victime s'aggrave pendant le transport, à 2 km de l'hôpital. Que fais-tu ?",o:["Nouveau bilan et rappel en urgence du médecin régulateur","Rien, l'hôpital est proche","Accélérer sans prévenir","Faire demi-tour vers le centre"],e:"En cas d'aggravation, nouveau bilan et rappel du régulateur, quelle que soit la distance restante (GDO Secours et soins d'urgence aux personnes 2022)"},
 {q:"Aux urgences, qui est responsable du transfert du brancard du VSAV à celui de l'hôpital ?",o:["Le personnel hospitalier, s'il est présent","Le chef d'agrès","Le conducteur","La victime"],e:"Le transfert du brancard est sous la responsabilité du personnel hospitalier s'il est présent (GDO Secours et soins d'urgence aux personnes 2022)"},
 {q:"Que faire des objets de valeur d'une victime non pris en compte par la police ?",o:["Les inventorier sur la fiche bilan puis les remettre à l'IAO","Les garder au centre de secours","Les laisser sur place","Les confier au premier témoin"],e:"Ils sont inventoriés sur la fiche bilan puis remis, après vérification, à l'IAO (GDO Secours et soins d'urgence aux personnes 2022)"},
 {q:"Quand les forces de l'ordre doivent-elles être invitées à monter dans le VSAV ?",o:["Quand la victime est violente, dangereuse ou menottée","Pour toute victime mineure","Jamais","Uniquement la nuit"],e:"Les forces de l'ordre doivent monter à bord dès que la victime est violente, dangereuse ou menottée (GDO Secours et soins d'urgence aux personnes 2022)"},
 {q:"Pendant les déplacements du VSAV, qui doit être ceinturé ?",o:["Tous les occupants (sauf justification médicale pour la victime)","Uniquement le conducteur","Uniquement la victime","Personne pendant les soins"],e:"Tous les occupants doivent être ceinturés à chaque phase de déplacement (GDO Secours et soins d'urgence aux personnes 2022)"},
 {q:"Évacuation d'un mineur : qui est recommandé dans la cellule sanitaire ?",o:["Le chef d'agrès et un équipier","Uniquement un équipier","Le conducteur","Personne, le parent suffit"],e:"Il est recommandé que le chef d'agrès et un équipier soient présents dans la cellule pendant l'évacuation d'un mineur (GDO Secours et soins d'urgence aux personnes 2022)"},
 {q:"Quel statut a un citoyen qui porte bénévolement assistance à une personne en péril grave et imminent ?",o:["Collaborateur occasionnel du service public","Sapeur-pompier volontaire","Témoin sans statut","Auxiliaire de police"],e:"Le citoyen sauveteur bénéficie de la qualité de collaborateur occasionnel du service public (GDO Secours et soins d'urgence aux personnes 2022)"},
 {q:"Qu'est-ce qu'une urgence fonctionnelle ?",o:["Vie non menacée immédiatement mais soins rapides nécessaires pour éviter un handicap","Une détresse vitale immédiate","Une demande de transport non urgente","Une urgence matérielle (porte, ascenseur)"],e:"L'urgence fonctionnelle nécessite des soins rapides et adaptés pour éviter un handicap (GDO Secours et soins d'urgence aux personnes 2022)"},
 {q:"Que regroupe la « conférence à trois » au traitement de l'appel ?",o:["L'appelant, l'opérateur du SIS et celui du SAMU","Le COS, le maire et le préfet","Trois sapeurs-pompiers","La victime, le médecin et la famille"],e:"La conférence à trois (appelant, opérateurs SIS et SAMU) facilite la prise en compte de l'opération (GDO Secours et soins d'urgence aux personnes 2022)"},
 {q:"Une victime saigne du nez. Que fais-tu ?",o:["Moucher, comprimer les deux narines au moins 10 min, tête penchée en avant","Tête en arrière et coton","Allonger sur le dos","Rien, cela s'arrête seul"],e:"Faire moucher, appuyer sur les deux narines au moins 10 minutes, tête penchée en avant (GDO Secours et soins d'urgence aux personnes 2022)"},
 {q:"Sur quelle base une contention physique peut-elle être réalisée ?",o:["Sur prescription d'un médecin présent sur les lieux","Sur décision du chef d'agrès","À la demande de la famille","Jamais"],e:"La contention physique est faite sur prescription d'un médecin présent sur les lieux, de façon proportionnée (GDO Secours et soins d'urgence aux personnes 2022)"},
 {q:"À quelle structure est rattachée la CUMP ?",o:["Au SAMU","Au SDIS","À la préfecture","À la mairie"],e:"La cellule d'urgence médico-psychologique est rattachée au SAMU (GDO Secours et soins d'urgence aux personnes 2022)"},
 {q:"SIS et SAMU n'ont pas la même lecture de l'urgence d'une intervention. Est-ce une carence ambulancière ?",o:["Non","Oui, toujours","Oui, si le VSAV est parti","Oui, si la victime est transportée"],e:"Une interprétation différente de la situation entre SIS et SAMU ne constitue pas une carence ambulancière (GDO Secours et soins d'urgence aux personnes 2022)"},
 {q:"Arrêt cardiaque : un témoin voit un DAE. Que lui fait faire l'opérateur ?",o:["Le mettre en œuvre","L'apporter seulement aux pompiers","Ne pas y toucher","Le ranger en sécurité"],e:"Si un DAE est visible du témoin, l'opérateur le lui fait mettre en œuvre ; le chef d'agrès le valorise ensuite (GDO Secours et soins d'urgence aux personnes 2022)"},
 {q:"Un renseignement est donné par un témoin et non constaté. Comment le noter sur la fiche bilan ?",o:["En indiquant qu'il s'agit des dires de la victime ou du témoin","Comme un constat du chef d'agrès","On ne le note pas","En le barrant"],e:"La réponse est consignée en précisant qu'il s'agit des dires de la victime ou d'un témoin (GDO Secours et soins d'urgence aux personnes 2022)"},
 {q:"Pourquoi faire couper les avertisseurs des renforts à l'approche d'une personne agitée ?",o:["Pour ne pas l'effrayer ou la provoquer","Pour économiser la batterie","Pour respecter le code de la route","Pour ne pas réveiller le quartier"],e:"Le chef d'agrès peut demander au CTA-CODIS de faire couper feux et deux-tons à l'approche (GDO Secours et soins d'urgence aux personnes 2022)"}
],
inc:[
 {q:"Quels sont les trois éléments du triangle du feu ?",o:["Combustible, comburant, énergie d'activation","Eau, air, chaleur","Fumée, flamme, chaleur","Combustible, fumée, oxygène"],e:"Supprimer un côté éteint le feu. Avec la réaction en chaîne, on parle de tétraèdre du feu."},
 {q:"Un feu de liquides ou de solides liquéfiables appartient à la classe :",o:["B","A","C","D"],e:"A : solides (braises). B : liquides et solides liquéfiables. C : gaz. D : métaux. F : huiles et graisses de cuisson."},
 {q:"Un feu d'huile de friteuse appartient à la classe :",o:["F","B","A","D"],e:"Classe F : huiles et graisses de cuisson."},
 {q:"Feu de friteuse dans une cuisine. Quel geste est proscrit ?",o:["Jeter de l'eau","Couper l'alimentation de la plaque","Couvrir avec un couvercle","Utiliser un extincteur de classe F"],e:"L'eau se vaporise sous l'huile et projette l'huile enflammée : boule de feu."},
 {q:"La propagation par les gaz chauds et les fumées s'appelle :",o:["La convection","La conduction","Le rayonnement","La projection"],e:"Conduction : à travers un matériau. Convection : par les gaz chauds. Rayonnement : à distance. Projection : particules enflammées."},
 {q:"Qu'est-ce que l'embrasement généralisé éclair (EGE, flashover) ?",o:["L'inflammation quasi simultanée de tout le contenu d'un local sous l'effet de la chaleur","L'explosion des fumées à l'ouverture d'une porte","L'effondrement d'une toiture","La reprise d'un feu après extinction"],e:"Signes : chaleur très intense, fumées chaudes qui descendent, flammes dans la couche de fumée (rollover)."},
 {q:"Quels signes font craindre une explosion de fumées (backdraft) ?",o:["Local clos, fumées pulsantes, vitres noircies, sifflements","Flammes vives par une fenêtre ouverte","Fumées blanches légères","Absence totale de fumée"],e:"Le local manque d'oxygène : un apport d'air brutal peut provoquer l'explosion."},
 {q:"Dans l'équipage d'un FPT à 6, que signifie BAT ?",o:["Binôme d'attaque","Brigade d'appui tactique","Binôme d'alimentation et de transport","Bataillon"],e:"Chef d'agrès, conducteur, binôme d'attaque (BAT) et binôme d'alimentation (BAL)."},
 {q:"Quel est le rôle principal du binôme d'alimentation (BAL) ?",o:["Alimenter l'engin en eau et renforcer le BAT","Mener seul les reconnaissances","Conduire l'engin","Rédiger les messages radio"],e:"Le BAL réalise l'alimentation (poteau, réserve) puis renforce l'action selon les ordres du chef d'agrès."},
 {q:"Quel est le débit nominal d'un poteau d'incendie de 100 mm ?",o:["60 m³/h sous 1 bar","30 m³/h sous 1 bar","120 m³/h sous 3 bars","10 m³/h"],e:"60 m³/h sous 1 bar de pression résiduelle, soit 1 000 L/min."},
 {q:"Quelle est la première phase de la marche générale des opérations ?",o:["Les reconnaissances","Les établissements","L'attaque","Le déblai"],e:"Reconnaissances, sauvetages et mises en sécurité, établissements, attaque, protection, déblai, surveillance."},
 {q:"Le mode d'action principal de l'eau sur un feu de classe A est :",o:["Le refroidissement","L'inhibition chimique","La dilution du combustible","L'isolement électrique"],e:"L'eau absorbe beaucoup de chaleur en se vaporisant ; la vapeur participe aussi à l'étouffement."},
 {q:"La ventilation par pression positive (VPP) consiste à :",o:["Mettre le volume en surpression avec un ventilateur et ouvrir un exutoire","Aspirer les fumées par la porte d'entrée","Ouvrir toutes les fenêtres au hasard","Couper la ventilation du bâtiment"],e:"Elle se décide après reconnaissance et se coordonne avec l'attaque."},
 {q:"À quoi sert le LSPCC ?",o:["Sauvetage et protection contre les chutes","Mesurer le CO","Alimenter un engin","Ventiler un local"],e:"Lot de sauvetage et de protection contre les chutes."},
 {q:"Quel est le débit nominal d'un poteau d'incendie de 150 mm ?",o:["120 m³/h","60 m³/h","90 m³/h","200 m³/h"],e:"PI 80 : 30 m³/h · PI 100 : 60 m³/h · PI 150 : 120 m³/h (GTO Établissements et techniques d'extinction, 2018)."},
 {q:"Combien de tours faut-il pour ouvrir complètement un PI 100 ?",o:["13 tours","7 tours","17 tours","25 tours"],e:"PI 80 et PI 100 : 13 tours · PI 150 : 17 tours (GTO Établissements 2018)."},
 {q:"Entre quelles pressions un point d'eau incendie doit-il fonctionner ?",o:["1 bar minimum et 16 bars maximum","0,5 bar minimum et 8 bars maximum","2 bars minimum et 10 bars maximum","3 bars minimum et 20 bars maximum"],e:"Un PEI doit fournir une pression minimale de 1 bar et maximale de 16 bars (GTO Établissements 2018)."},
 {q:"Sur un établissement, si on double le débit, les pertes de charge sont :",o:["Multipliées par 4","Multipliées par 2","Inchangées","Divisées par 2"],e:"Les pertes de charge sont proportionnelles à la longueur et au carré du débit, et inversement proportionnelles au diamètre (GTO Établissements 2018)."},
 {q:"Quelle pression représente une dénivelée de 10 mètres ?",o:["Environ 1 bar","Environ 0,1 bar","Environ 10 bars","Environ 5 bars"],e:"On compte 1 bar par 10 m de dénivelée : à prendre en compte en montant les étages (GTO Établissements 2018)."},
 {q:"Par quel mot se termine l'ordre d'exécution d'un établissement ?",o:["« Établissez »","« En reconnaissance »","« Exécution »","« Alimentez »"],e:"L'ordre préparatoire se termine par « … en reconnaissance », l'ordre d'exécution par « … établissez ». Les restrictions se donnent avant « établissez » (GTO Établissements 2018)."},
 {q:"Que précise un ordre d'établissement ?",o:["Le moyen, l'emplacement, le cheminement, la mission et la sécurité","Le nom des équipiers et l'heure d'arrivée","Uniquement le diamètre des tuyaux","Le numéro du PI et sa pression"],e:"Un ordre donne : nature du moyen, emplacement, cheminement, mission et consignes de sécurité (GTO Établissements 2018)."},
 {q:"Feu dans un immeuble : d'où établit-on la lance en superstructure ?",o:["Depuis l'étage inférieur au feu (N-1)","Depuis l'étage du feu, devant la porte","Depuis l'étage supérieur (N+1)","Toujours depuis la rue"],e:"On s'établit à l'extérieur d'un volume de plain-pied, au niveau N-1 en superstructure, hors de la zone de propagation en infrastructure (GTO Établissements 2018)."},
 {q:"Dans le binôme d'attaque, qui est porte-lance ?",o:["Le chef d'équipe","L'équipier","Le chef d'agrès","Le conducteur"],e:"Le chef d'équipe tient la lance. L'équipier est double porte-lance : il aide à la manœuvre et gère le tuyau. Ensemble, ils couvrent une vision à 360° (GTO Établissements 2018)."},
 {q:"Refroidissement des fumées par impulsions courtes : quelle durée d'impulsion ?",o:["0,5 seconde maximum","2 à 5 secondes","10 secondes","Jet continu"],e:"Impulsions courtes : 0,5 s au plus, 100 à 250 L/min, lance inclinée de 30 à 60°. Les impulsions longues (2 à 5 s) servent dans les grands volumes (GTO Établissements 2018)."},
 {q:"Des langues de feu (« rollovers ») courent sous le plafond dans les fumées. Que fais-tu ?",o:["Je ne progresse pas dessous et je me replie : l'EGE est imminent","Je progresse vite pour atteindre le foyer","Je ventile immédiatement par le haut","Je coupe la lance pour économiser l'eau"],e:"Les rollovers annoncent un embrasement généralisé éclair. On ne progresse jamais dessous, on se replie (GTO Établissements 2018)."},
 {q:"En dernier recours, comment le binôme se protège-t-il d'un embrasement ?",o:["Face au sol, lance au-dessus des casques en jet diffusé de protection au débit maximal","Debout, en jet droit vers le foyer","En fermant la lance et en courant vers la sortie","En retirant le masque pour mieux voir"],e:"Position de protection ultime : binôme allongé face au sol, lance au-dessus des casques en jet diffusé de protection, débit maximal (GTO Établissements 2018)."},
 {q:"Attaque d'atténuation depuis l'extérieur : quel jet utilises-tu ?",o:["Un jet droit à travers l'ouverture, dirigé vers le plafond","Un jet diffusé d'attaque devant la fenêtre","Un jet diffusé de protection","Un jet droit dirigé vers le sol"],e:"Jet droit par l'ouverture vers le plafond, 250 L/min minimum. Un jet diffusé n'a pas d'effet dans ce cas (GTO Établissements 2018)."},
 {q:"Feu attisé par le vent (effet chalumeau). Comment attaques-tu ?",o:["Avec le vent dans le dos","Face au vent","Perpendiculairement au vent, sans protection","Par le côté où sortent les flammes"],e:"On attaque avec le vent dans le dos. Un stoppeur de vent peut limiter l'apport d'air (GTO Établissements 2018)."},
 {q:"Quels sont les trois objectifs de la ventilation opérationnelle ?",o:["Protéger, désenfumer, attaquer","Éteindre, refroidir, déblayer","Sauver, alimenter, surveiller","Reconnaître, établir, ventiler"],e:"Ventilation de protection, de désenfumage et d'attaque (GTO Ventilation opérationnelle, 2019)."},
 {q:"En ventilation opérationnelle, qu'appelle-t-on le « sortant » ?",o:["L'ouvrant par lequel sortent les fumées, au niveau du feu ou au-dessus","L'ouvrant par lequel entre l'air frais","La porte d'accès des pompiers","Le ventilateur lui-même"],e:"L'entrant laisse entrer l'air (au niveau du feu ou en dessous), le sortant évacue les fumées (au niveau du feu ou au-dessus) (GTO Ventilation 2019)."},
 {q:"À quelle distance de l'ouvrant place-t-on un ventilateur thermique ?",o:["Une distance égale à la hauteur de l'ouvrant","Toujours collé à l'ouvrant","10 mètres minimum","À l'intérieur du local"],e:"Le cône d'air doit couvrir tout l'ouvrant : on place le ventilateur à une distance égale à la hauteur de l'ouverture (GTO Ventilation 2019)."},
 {q:"Quand est-il interdit de ventiler pour attaquer ?",o:["Si des victimes ou des pompiers sont entre le feu et le sortant","Si le feu est au rez-de-chaussée","S'il fait nuit","Si le local a une fenêtre"],e:"La ventilation pousse les fumées et la chaleur vers le sortant : personne ne doit se trouver sur ce trajet (GTO Ventilation 2019)."},
 {q:"Quel risque présente un ventilateur thermique ?",o:["Il rejette du monoxyde de carbone (CO)","Il produit de l'électricité statique dangereuse","Il aspire les fumées vers l'extérieur","Il refroidit trop le local"],e:"Le moteur thermique rejette du CO. Une VPP bien menée peut atteindre 100 ppm : il faut surveiller l'atmosphère (GTO Ventilation 2019)."},
 {q:"La cagoule de protection filtrante :",o:["Arrête suies et particules fines, mais ne filtre pas les gaz","Remplace l'ARI sur un feu de structure","Filtre le monoxyde de carbone","Se porte uniquement sous l'ARI"],e:"Elle protège tête, cou et épaules des suies et particules, hors phases sous ARI. Elle ne filtre pas les gaz (GDO Toxicité des fumées, 2020)."},
 {q:"Quelles zones de peau absorbent le plus les polluants des fumées ?",o:["Le visage et le cou, où la peau est la plus fine","Les paumes des mains","Les pieds","Le dos"],e:"Visage et cou sont les plus sensibles. La chaleur et l'humidité de la peau augmentent encore l'absorption (GDO Toxicité des fumées 2020)."},
 {q:"Pendant une pause sur feu, avant de boire et manger, tu dois :",o:["Retirer les EPI et te nettoyer visage, cou et mains (lingettes ou eau froide savonneuse)","Garder ta tenue pour gagner du temps","Te rincer à l'eau chaude","Retirer seulement le casque"],e:"Après retrait des EPI, nettoyage du visage, du cou et des mains avant de s'hydrater et se restaurer, dans un espace dédié de la zone de soutien (GDO Toxicité des fumées 2020)."},
 {q:"À l'arrivée sur un feu, comment stationner les engins ?",o:["Vitres et ventilations fermées, même hors des fumées","Vitres ouvertes pour entendre les ordres","Moteur coupé, portes ouvertes","Dans l'axe du panache pour voir le feu"],e:"Engins stationnés vitres et ventilations fermées, pour ne pas contaminer les cabines (GDO Toxicité des fumées 2020)."},
 {q:"À quelle pression environ retentit le sifflet de fin de charge d'un ARI ?",o:["Environ 55 bar","Environ 100 bar","Environ 20 bar","Environ 150 bar"],e:"Le sifflet retentit vers 55 bar : retour immédiat et systématique vers le point de pénétration (GTO Engagement en milieu vicié 2024)"},
 {q:"Que doit faire le binôme quand le sifflet de fin de charge retentit ?",o:["Revenir immédiatement vers le point de pénétration","Terminer la mission en cours puis sortir","Réduire sa consommation et continuer","Prévenir le contrôleur et attendre ses ordres"],e:"Le sifflet impose un retour immédiat et systématique ; le retour peut d'ailleurs être anticipé avant le sifflet (GTO Engagement en milieu vicié 2024)"},
 {q:"Quelle est la masse maximale d'un ARI prêt à l'emploi selon la norme NF EN 137 ?",o:["18 kg","12 kg","25 kg","15 kg"],e:"La norme NF EN 137 limite l'ARI prêt à l'emploi à 18 kg (GTO Engagement en milieu vicié 2024)"},
 {q:"Quelles sont les pressions de service usuelles des bouteilles d'ARI ?",o:["200 ou 300 bar","100 ou 150 bar","400 ou 500 bar","50 ou 80 bar"],e:"La haute pression des bouteilles est de 200 ou 300 bar ; la moyenne pression de 6 à 8 bar (GTO Engagement en milieu vicié 2024)"},
 {q:"Quelle quantité d'air contient environ une bouteille de 7 L à 300 bar ?",o:["Environ 1 900 L","Environ 2 100 L","Environ 700 L","Environ 3 000 L"],e:"Capacité = P×V/(Z×Patm) = 300×7/(1,1×1) ≈ 1 909 L (Z = 1,1 à 300 bar) (GTO Engagement en milieu vicié 2024)"},
 {q:"Avec une consommation de 100 L/min, quelle est l'autonomie théorique d'une bouteille de 7 L à 300 bar ?",o:["Environ 19 minutes","Environ 30 minutes","Environ 10 minutes","Environ 45 minutes"],e:"1 909 L / 100 L/min ≈ 19 minutes (GTO Engagement en milieu vicié 2024)"},
 {q:"Quelle consommation moyenne retient-on pour une activité de sauvetage et de lutte contre l'incendie sous ARI ?",o:["100 L/min","40 L/min","10 L/min","200 L/min"],e:"Le calcul théorique retient une consommation moyenne de 100 L/min ; elle va de 10 L/min au repos à 135 L/min (GTO Engagement en milieu vicié 2024)"},
 {q:"Sur une ligne guide, que signifie 1 olive (syllabe « vie ») ?",o:["La direction de la sortie","La direction du feu","Une dérivation","Un point d'arrêt"],e:"1 olive = « vie » = vers la sortie ; 3 olives = « in-cen-die » = vers le feu (GTO Engagement en milieu vicié 2024)"},
 {q:"Sur une ligne guide, que signifient 3 olives ?",o:["La direction du feu (« in-cen-die »)","La direction de la sortie","La fin de la ligne","Une victime à proximité"],e:"3 olives, comme les 3 syllabes « in-cen-die », indiquent la direction du feu (GTO Engagement en milieu vicié 2024)"},
 {q:"Qu'est-ce qu'une ligne de vie ?",o:["Une ligne guide + une liaison personnelle","Une corde de sauvetage du LSPCC","Le tuyau de l'établissement","La liaison radio avec le contrôleur"],e:"Ligne de vie = ligne guide + liaison personnelle (GTO Engagement en milieu vicié 2024)"},
 {q:"Comment se réalise le contrôle croisé avant l'engagement sous ARI ?",o:["Face à face entre équipiers, validé par le chef d'agrès ou le contrôleur","Par chaque porteur seul devant un miroir","Uniquement par le contrôleur, sans les porteurs","Après l'entrée dans le volume"],e:"Le contrôle croisé se fait face à face et est validé par le chef d'agrès ou le contrôleur (GTO Engagement en milieu vicié 2024)"},
 {q:"Avant l'engagement, comment le binôme ouvre-t-il les bouteilles ?",o:["Lentement et complètement, en vérifiant sifflet et manomètre","D'un quart de tour pour économiser l'air","Rapidement, sans vérifier le manomètre","Seulement une fois dans le volume"],e:"Ouverture lente et complète, contrôle du sifflet et du manomètre (GTO Engagement en milieu vicié 2024)"},
 {q:"Qui gère le tableau de gestion des porteurs (TGP) ?",o:["Le contrôleur","Le chef de binôme","Le conducteur","Le COS uniquement"],e:"Le contrôleur gère le TGP, est à l'écoute des binômes et engage le binôme de sécurité (GTO Engagement en milieu vicié 2024)"},
 {q:"Une fois le binôme de sécurité engagé, que faut-il faire ?",o:["Désigner dès que possible un nouveau binôme de sécurité","Rien, il n'y a qu'un binôme de sécurité","Engager tous les binômes restants","Arrêter toute l'intervention"],e:"Un nouveau binôme de sécurité doit être désigné dès que possible (GTO Engagement en milieu vicié 2024)"},
 {q:"Que doit armer chaque porteur avant l'engagement, en plus de fermer la boucle ventrale et la mentonnière ?",o:["La balise de détresse","La lampe de casque","La caméra thermique","Le sifflet de fin de charge"],e:"Chaque porteur ferme la boucle ventrale, attache la mentonnière et arme sa balise de détresse (GTO Engagement en milieu vicié 2024)"},
 {q:"Quel moyen permet d'évacuer une victime en milieu vicié en la protégeant des fumées ?",o:["La cagoule d'évacuation","Un masque chirurgical","Un drap mouillé","La couverture de survie"],e:"La cagoule d'évacuation est confiée au sauveteur disposant de la plus grande autonomie (GTO Engagement en milieu vicié 2024)"},
 {q:"À qui confie-t-on la cagoule d'évacuation d'une victime ?",o:["Au sauveteur ayant la plus grande autonomie","Au plus jeune du binôme","Au chef d'agrès resté dehors","À la victime elle-même"],e:"Le sauveteur ayant le plus d'air restant prend en charge la cagoule d'évacuation (GTO Engagement en milieu vicié 2024)"},
 {q:"Quelles sont les méthodes de reconnaissance d'un volume en milieu vicié ?",o:["Circulaire, latérale (associée/dissociée), va-et-vient","Verticale, horizontale, diagonale","En étoile, en spirale, en croix","Rapide, lente, intermédiaire"],e:"Le GTO décrit les méthodes circulaire, latérale (associée ou dissociée) et en va-et-vient (GTO Engagement en milieu vicié 2024)"},
 {q:"Que doit couvrir l'autonomie en air calculée avant engagement ?",o:["L'aller, la mission et le retour","Uniquement l'aller","Uniquement la mission","La mission et 5 minutes de marge"],e:"L'autonomie doit couvrir l'aller-retour plus la mission ; le stress augmente la consommation (GTO Engagement en milieu vicié 2024)"},
 {q:"À quelle distance du mur doit se trouver le pied d'une échelle à main pour être stable ?",o:["Environ 1/3 de la longueur développée","Environ 1/10 de la longueur développée","Environ la moitié de la longueur développée","Contre le mur"],e:"Le piétage doit être d'environ 1/3 de la longueur développée : ni trop développée, ni trop inclinée (GTO Sauvetages et mises en sécurité)"},
 {q:"Jusqu'à quel étage permet d'accéder une échelle à coulisse deux plans ?",o:["Au 1er et 2e étage","Au 4e étage","Au 6e étage","Au rez-de-chaussée seulement"],e:"Les échelles à coulisse sont utilisées pour rétablir les communications et atteindre les 1er et 2e étages (GTO Sauvetages et mises en sécurité)"},
 {q:"Quel étage permet d'atteindre l'échelle à coulisse trois plans avec arcs-boutants ?",o:["Le 4e étage","Le 2e étage","Le 8e étage","Le 1er étage"],e:"L'échelle à coulisse trois plans permet d'accéder au 4e étage (GTO Sauvetages et mises en sécurité)"},
 {q:"Que signifie LSPCC ?",o:["Lot de sauvetage et de protection contre les chutes","Lot de secours pour personnes en chute contrôlée","Ligne de sécurité pour pompiers en cage d'escalier","Lot spécial de protection des colonnes"],e:"LSPCC = lot de sauvetage et de protection contre les chutes (GTO Sauvetages et mises en sécurité)"},
 {q:"Quelle est la longueur de la corde du lot de sauvetage « engin » ?",o:["30 m","60 m","15 m","100 m"],e:"Corde semi-statique de 30 m pour le lot « engin », 60 m pour le lot « échelle » (GTO Sauvetages et mises en sécurité)"},
 {q:"Quelle est la longueur de la corde du lot de sauvetage « échelle » ?",o:["60 m","30 m","45 m","20 m"],e:"Le lot « échelle » comprend une corde semi-statique de 60 m (GTO Sauvetages et mises en sécurité)"},
 {q:"Qu'est-ce que le facteur de chute ?",o:["Le rapport hauteur de chute / longueur de corde qui amortit la chute","La vitesse de la chute","Le poids de la victime divisé par la hauteur","Le nombre d'amarrages utilisés"],e:"FC = H (hauteur de chute) / L (longueur de corde qui amortit) (GTO Sauvetages et mises en sécurité)"},
 {q:"Par où la mise en sécurité doit-elle s'effectuer en priorité ?",o:["Par les communications existantes","Par les échelles aériennes","Par les fenêtres","Par le toit"],e:"La mise en sécurité s'effectue prioritairement par les communications existantes (GTO Sauvetages et mises en sécurité)"},
 {q:"Quand un dégagement d'urgence doit-il être réalisé ?",o:["Quand le danger est réel, immédiat, vital et non contrôlable","Dès qu'une victime est trouvée","Uniquement sur ordre du médecin","Quand la victime le demande"],e:"Le dégagement d'urgence n'est justifié que si le danger est réel, immédiat, vital et non contrôlable (GTO Sauvetages et mises en sécurité)"},
 {q:"Peut-on laisser seule une victime qui vient d'être déplacée ?",o:["Non, jamais","Oui, si elle est consciente","Oui, si elle est hors de la zone de danger","Oui, pendant moins de 5 minutes"],e:"Dans tous les cas, une victime déplacée ne doit jamais être laissée seule (GTO Sauvetages et mises en sécurité)"},
 {q:"Quelle masse par personne retient-on pour la charge d'un panier de MEA ?",o:["90 kg","75 kg","100 kg","120 kg"],e:"La charge par personne est calculée sur une masse supposée de 90 kg (GTO Sauvetages et mises en sécurité)"},
 {q:"Que peut-on utiliser pour prolonger un moyen élévateur aérien ?",o:["Une échelle à crochets","Une échelle à coulisse 3 plans","Une corde de 60 m","Un tuyau de 45"],e:"La prolongation d'un MEA est possible au moyen d'une échelle à crochets (GTO Sauvetages et mises en sécurité)"},
 {q:"Quelle est la mission du binôme de sauvetage ?",o:["Le sauvetage d'un ou de sapeurs-pompiers, mission exclusive et prioritaire","L'extinction du foyer principal","La ventilation","La reconnaissance des étages supérieurs"],e:"Le binôme de sauvetage a une mission exclusive et prioritaire : sauver des sapeurs-pompiers (GTO Sauvegarde des SP en milieu vicié / auto-sauvetage)"},
 {q:"Qui peut déclencher le signal d'évacuation d'urgence ?",o:["Le COS, l'officier sécurité ou un chef de secteur","N'importe quel équipier","Uniquement le CODIS","Uniquement le chef d'agrès du premier engin"],e:"Il est déclenché sur ordre du COS, de l'officier sécurité ou d'un chef de secteur (GTO Sauvegarde des SP en milieu vicié / auto-sauvetage)"},
 {q:"Une fois un MEA positionné comme itinéraire de secours, peut-on l'utiliser pour l'attaque ?",o:["Non, il est uniquement dévolu à cette fonction","Oui, s'il reste de la place dans le panier","Oui, sur ordre du chef d'agrès","Oui, une fois le feu maîtrisé seulement"],e:"Un MEA positionné en itinéraire de secours doit être uniquement dévolu à cette fonction (GTO Sauvegarde des SP en milieu vicié / auto-sauvetage)"},
 {q:"Dans quelle position un SP en attente de secours doit-il se placer pour économiser l'air ?",o:["Assis jambes sur les côtés ou allongé sur le flanc","Debout contre un mur","À genoux, bras levés","En marchant lentement"],e:"La position d'attente doit être la plus économique possible en oxygène (GTO Sauvegarde des SP en milieu vicié / auto-sauvetage)"},
 {q:"Quand le retrait de l'ARI pour franchir un obstacle est-il autorisé ?",o:["Uniquement en dernier recours","Systématiquement pour gagner du temps","Dès que l'obstacle fait plus d'1 m","Jamais, en aucun cas"],e:"Le retrait de l'ARI n'est mis en œuvre qu'en dernier recours, si les autres techniques échouent (GTO Sauvegarde des SP en milieu vicié / auto-sauvetage)"},
 {q:"Sauf circonstances exceptionnelles, le binôme en milieu vicié peut-il se séparer ?",o:["Non, il doit rester indissociable","Oui, pour couvrir plus vite le volume","Oui, si chacun a une ligne guide","Oui, sur décision du chef de binôme"],e:"Sauf circonstances exceptionnelles et imprévues, le binôme reste indissociable (GTO Sauvegarde des SP en milieu vicié / auto-sauvetage)"},
 {q:"En VPP, quel rapport de surface sortant/entrant donne environ 90 % du débit maximal ?",o:["Sortant = 2 fois l'entrant","Sortant = moitié de l'entrant","Sortant = entrant","Sortant = 10 fois l'entrant"],e:"Environ 90 % du débit max quand le sortant a une surface double de l'entrant ; au-delà, peu d'effet (GTO Ventilation opérationnelle 2019)"},
 {q:"Au-delà de quelle vitesse un vent contraire sur le sortant rend le désenfumage peu efficace ?",o:["18 km/h (5 m/s)","5 km/h","50 km/h","100 km/h"],e:"Si le vent vers le sortant dépasse 18 km/h (5 m/s), la technique perd en efficacité (GTO Ventilation opérationnelle 2019)"},
 {q:"En ventilation d'attaque, où ne doit-on jamais placer d'intervenants ?",o:["Entre le foyer et le sortant","Derrière le ventilateur","À l'entrant","Dans le local sain"],e:"Aucune action ne doit placer des intervenants entre le foyer et le sortant (GTO Ventilation opérationnelle 2019)"},
 {q:"« Ventiler pour protéger » des locaux adjacents consiste à :",o:["Mettre le local sain en surpression par rapport au local en feu","Ouvrir toutes les fenêtres","Créer un sortant dans le local sain","Arrêter les ventilateurs"],e:"Le local sain est mis en surpression par rapport au local en feu (GTO Ventilation opérationnelle 2019)"},
 {q:"Quel débit sort d'un exutoire de 1 m² à 5 m/s ?",o:["Environ 18 000 m³/h","Environ 1 800 m³/h","Environ 180 m³/h","Environ 180 000 m³/h"],e:"5 m/s × 1 m² × 3 600 s = 18 000 m³/h, soit un appartement de 120 m² par minute (GTO Ventilation opérationnelle 2019)"},
 {q:"Jusqu'à quelle température les produits de pyrolyse ne sont-ils pas inflammables ?",o:["280 °C","100 °C","500 °C","1 000 °C"],e:"Jusqu'à 280 °C, produits non inflammables (endothermique) ; de 280 à 500 °C, ils peuvent s'enflammer (GDO Prévention des risques liés à la toxicité des fumées 2020)"},
 {q:"En zone d'exclusion d'un feu, le port de l'ARI est :",o:["Permanent jusqu'à la fin de l'opération","Facultatif après l'extinction","Laissé au choix de chacun","Obligatoire seulement pour l'attaque"],e:"La zone d'exclusion nécessite un port permanent de l'ARI jusqu'à la fin de l'opération, déblai compris (GDO Prévention des risques liés à la toxicité des fumées 2020)"},
 {q:"Où installe-t-on la zone de réhabilitation sur un feu de structure ?",o:["En zone orange, hors du panache de fumées","Dans la zone d'exclusion","Sous le vent du feu","Dans le bâtiment voisin"],e:"La zone de réhabilitation est installée hors du panache, en zone orange (hors zone brûlée en feu d'espace naturel) (GDO Prévention des risques liés à la toxicité des fumées 2020)"},
 {q:"Sous la douche après un feu, quelle zone faut-il brosser avec insistance ?",o:["Le cou et les zones de liaison entre EPI","Les pieds uniquement","Le dos uniquement","Les cheveux uniquement"],e:"Insister sur les zones de liaison entre EPI et là où les couches sont les plus fines, le cou notamment (GDO Prévention des risques liés à la toxicité des fumées 2020)"},
 {q:"À l'arrivée sur un feu, comment laisser les engins ?",o:["Vitres et ventilations fermées","Vitres ouvertes pour aérer","Moteur coupé et portes ouvertes","Climatisation en air extérieur"],e:"Privilégier un stationnement vitres et ventilations fermées, même hors de la zone exposée aux fumées (GDO Prévention des risques liés à la toxicité des fumées 2020)"},
 {q:"Qu'est-ce que la contamination indirecte (croisée) ?",o:["S'exposer aux polluants via un objet ou élément souillé","Respirer les fumées sans ARI","Être brûlé par contact","Boire de l'eau contaminée"],e:"Un personnel isolé de la zone sale s'expose via un vecteur intermédiaire pollué (GDO Prévention des risques liés à la toxicité des fumées 2020)"},
 {q:"Combien de tuyaux semi-rigides comprend la lance du dévidoir tournant (LDT) ?",o:["40 à 80 m de tuyaux de 23 ou 33 mm","200 m de tuyaux de 70 mm","20 m de tuyaux de 45 mm","120 m de tuyaux de 110 mm"],e:"La LDT est constituée de 40 à 80 m de tuyaux semi-rigides de 23 ou 33 mm (GTO Établissements et techniques d'extinction 2018)"},
 {q:"De quoi se compose généralement une ligne d'attaque ?",o:["Une lance et 2 ou 3 tuyaux de 45","Une lance et 10 tuyaux de 70","Un tuyau de 110","Une lance canon"],e:"Une ligne d'attaque : une lance connectée à 2 ou 3 tuyaux souples de diamètre 45 (GTO Établissements et techniques d'extinction 2018)"},
 {q:"Jusqu'à quel pourcentage de ses capacités fait-on travailler une pompe ?",o:["80 % maximum","100 %","50 % maximum","120 %"],e:"On évite de dépasser 80 % des capacités pour préserver la pompe et éviter une rupture hydraulique (GTO Établissements et techniques d'extinction 2018)"},
 {q:"En risque courant important, quelle distance entre deux PEI ?",o:["200 m","50 m","500 m","1 km"],e:"Généralement 200 m, car les dévidoirs sont armés de 200 m de tuyaux de 70 mm (GTO Établissements et techniques d'extinction 2018)"},
 {q:"Quand un PEI est-il considéré « haute pression » ?",o:["Pression dynamique > 6 bar à 60 m³/h","Pression statique > 1 bar","Débit > 30 m³/h","Pression > 16 bar"],e:"Est considéré haute pression un PEI dont la pression dynamique à 60 m³/h dépasse 6 bar (GTO Établissements et techniques d'extinction 2018)"},
 {q:"À combien de mètres d'eau correspond la pression atmosphérique au niveau de la mer ?",o:["10,33 m (1,013 bar)","1 m","33 m","100 m"],e:"La pression atmosphérique vaut 10,33 m d'eau, soit 1,013 bar (Torricelli) (GTO Établissements et techniques d'extinction 2018)"},
 {q:"Quelle surface minimale pour une aire d'aspiration destinée à un poids lourd ?",o:["8 m × 4 m","4 m × 3 m","2 m × 2 m","20 m × 10 m"],e:"Aire d'aspiration : 4 × 3 m par motopompe remorquable, 8 × 4 m par poids lourd au minimum (GTO Établissements et techniques d'extinction 2018)"},
 {q:"Malgré l'action de ta lance, la chaleur ressentie persiste. Qu'en déduis-tu ?",o:["L'équipe ne prend pas le dessus sur le feu","Le feu est éteint","La tenue est défectueuse","Il faut fermer la lance"],e:"La persistance de la chaleur malgré l'action de lance signifie que l'équipe ne prend pas le dessus (GTO Établissements et techniques d'extinction 2018)"},
 {q:"Quelle unité utilise-t-on pour le débit d'une lance ? Et pour une ressource en eau ?",o:["L/min pour la lance, m³/h pour la ressource","m³/h pour la lance, L/min pour la ressource","bar pour les deux","L/s pour les deux"],e:"L/min pour les lances et les pompes ; m³/h pour les ressources en eau (hydrants) (GTO Établissements et techniques d'extinction 2018)"}
],
div:[
 {q:"Un essaim d'abeilles est posé dans un jardin, sans danger immédiat. Quelle orientation ?",o:["Faire appel à un apiculteur","Détruire l'essaim à l'insecticide","Arroser l'essaim à la lance","Laisser le requérant le déplacer seul"],e:"Les abeilles sont utiles et protégées : on oriente vers un apiculteur, sauf danger particulier."},
 {q:"Destruction d'un nid de frelons : quelle protection pour l'intervenant ?",o:["Une tenue spécifique de protection contre les hyménoptères","La tenue de feu sans gants","Un ARI","Aucune s'il agit vite"],e:"Tenue intégrale avec voilette et gants. Prévoir la sécurité du public et le travail en hauteur."},
 {q:"Avant d'épuiser une cave inondée, que vérifies-tu en priorité ?",o:["Que l'électricité est coupée","Que la motopompe est neuve","Que le propriétaire est présent","La couleur de l'eau"],e:"Risque d'électrisation : couper l'électricité avant d'entrer dans l'eau."},
 {q:"Personne bloquée dans un ascenseur, sans détresse. Avant toute manœuvre :",o:["Couper l'alimentation électrique de la machinerie","Forcer les portes palières","Demander à la personne de sauter","Remettre le courant pour tester"],e:"On consigne l'énergie, on rassure la personne, on suit la procédure. L'ascensoriste est souvent sollicité."},
 {q:"Une odeur de gaz est signalée dans un logement. Quel geste est proscrit ?",o:["Actionner les interrupteurs","Couper le gaz au compteur","Aérer","Faire évacuer"],e:"Aucune étincelle : ni interrupteur, ni sonnette, ni téléphone dans la zone. Couper, aérer, évacuer, prévenir le distributeur."},
 {q:"Arbre tombé sur la chaussée : quel EPI est propre au tronçonnage ?",o:["Pantalon anti-coupure","Tenue contre les hyménoptères","ARI","Gilet de sauvetage"],e:"Pantalon et gants anti-coupure, casque à visière, protection auditive. Le balisage vient en premier."},
 {q:"Ouverture de porte : quand l'intervention est-elle justifiée ?",o:["Quand une personne est en danger ou présumée en détresse","Dès qu'un habitant a perdu ses clés","Pour un litige entre voisins","Sur simple demande du propriétaire"],e:"Sans danger pour une personne, l'ouverture relève d'un serrurier."},
 {q:"Flaque d'hydrocarbures sur la chaussée après un accident. Que fais-tu ?",o:["Je balise puis j'étends un produit absorbant","Je la dilue au jet vers l'égout","Je la laisse sécher","Je l'enflamme"],e:"On évite la pollution des réseaux et on prévient le gestionnaire de voirie."},
 {q:"Avec quoi odorise-t-on le gaz naturel de réseau ?",o:["Du THT (tétrahydrothiophène)","Du monoxyde de carbone","Rien, il sent naturellement","De l'ammoniac"],e:"Le THT est souvent confondu avec le mercaptan, encore utilisé pour le gaz en bouteille (GDO Interventions en présence de gaz, 2021)."},
 {q:"Gaz naturel et butane/propane, par rapport à l'air :",o:["Le gaz naturel est plus léger, le butane et le propane plus lourds","Tous sont plus lourds","Tous sont plus légers","Le gaz naturel est plus lourd, le butane plus léger"],e:"Le gaz naturel (méthane) monte, le butane et le propane s'accumulent en points bas : caves, regards, vides sanitaires (GDO Gaz 2021)."},
 {q:"Fuite sur le réseau de gaz naturel : quel zonage par défaut ?",o:["Zone d'exclusion d'environ 50 m, zone contrôlée d'environ 100 m","Zone d'exclusion de 10 m seulement","Zone d'exclusion de 500 m","Aucun zonage, on attend GRDF"],e:"Périmètres par défaut des conventions SIS/GRDF. Pour les réseaux à périmètre étendu : 110 m et 180 m (GDO Gaz 2021)."},
 {q:"Comment ferme-t-on la plupart des organes de coupure de gaz ?",o:["Un quart de tour vers la droite (sens des aiguilles d'une montre)","Plusieurs tours vers la gauche","En tirant la manette vers soi","En dévissant complètement le robinet"],e:"Indicateur perpendiculaire à la conduite = fermé. Il existe des exceptions (quart de tour à gauche dans certains immeubles anciens) (GDO Gaz 2021)."},
 {q:"Le gaz a été coupé. Peut-on le rouvrir une fois la fuite traitée ?",o:["Non, jamais : c'est le rôle de l'exploitant","Oui, si plus aucune odeur n'est perçue","Oui, sur demande de l'occupant","Oui, après 30 minutes"],e:"Les sapeurs-pompiers ne rouvrent jamais le gaz une fois fermé (GDO Gaz 2021)."},
 {q:"Que signifie PGR ?",o:["Procédure gaz renforcée","Plan général de risque","Protection gaz réseau","Périmètre gaz restreint"],e:"La PGR organise la stratégie interservices SIS/GRDF, par exemple pour une fuite sur la voie publique ou un coffret en façade enflammé (GDO Gaz 2021)."},
 {q:"Canalisation de gaz à moins de 16 bar : quel rayon de zone d'exclusion ?",o:["En mètres, égal au diamètre de la canalisation en millimètres","Toujours 10 mètres","Le double de la profondeur d'enfouissement","100 mètres quel que soit le diamètre"],e:"Moyen mnémotechnique majorant : canalisation de 600 mm → 600 m (GDO Gaz 2021)."},
 {q:"Un mélange gaz/air peut exploser si sa concentration est :",o:["Comprise entre la LIE et la LSE","Inférieure à la LIE","Supérieure à la LSE","Égale à 100 %"],e:"Il faut aussi un comburant, une source d'inflammation et souvent un milieu confiné. L'explosimètre mesure en % de la LIE (GDO Gaz 2021)."},
 {q:"Combien de temps refroidir au minimum une bouteille d'acétylène exposée au feu ?",o:["1 heure","5 minutes","15 minutes","24 heures"],e:"La durée de refroidissement d'une bouteille d'acétylène est d'une heure minimum (GDO Gaz 2021)."},
 {q:"Conseil à un particulier qui sent le gaz : comment prévenir les voisins ?",o:["En frappant à leur porte, sans sonner","En les appelant au téléphone depuis le logement","En sonnant","En allumant les lumières du palier"],e:"Pas d'électricité (sonnette, interrupteur, téléphone). On aère, on sort sans ascenseur, et si le gaz brûle on n'essaie pas d'éteindre (GDO Gaz 2021)."},
 {q:"Fuite de gaz : pourquoi constituer un binôme de sécurité ?",o:["Pour intervenir sans délai en cas d'explosion, depuis l'extérieur de la zone d'exclusion","Pour couper le gaz plus vite","Pour aérer le logement","Pour remplacer le binôme engagé"],e:"Ce binôme reste hors zone d'exclusion et protégé, avec le matériel prêt (engin alimenté, dévidoirs descendus), et passe un message si besoin (GDO Gaz 2021)."},
 {q:"Lance en eau près d'une installation électrique haute tension : distance minimale ?",o:["5 m en jet diffusé d'attaque, 10 m en jet droit","1 m en jet droit","Aucune, l'eau ne conduit pas","50 m dans tous les cas"],e:"Distances minimales entre l'eau projetée et une installation HTA ou HTB (GDO Opérations en présence d'électricité, 2024)."},
 {q:"Câble électrique tombé au sol : comment te déplaces-tu près de la zone ?",o:["À petits pas, pour limiter la tension de pas","En courant","À grandes enjambées","En rampant"],e:"La tension de pas est la différence de potentiel entre les deux pieds près d'un point d'entrée du courant dans le sol (GDO Électricité 2024)."},
 {q:"Peut-on entrer dans un poste électrique haute tension sans l'exploitant ?",o:["Non, jamais sans un agent Enedis ou RTE","Oui, si on porte des gants","Oui, s'il y a un feu","Oui, après avoir coupé le disjoncteur"],e:"Pas de pénétration dans les postes électriques sans un technicien RTE ou Enedis. Le COS et l'exploitant forment un binôme (GDO Électricité 2024)."},
 {q:"Malaise d'une personne dans un silo. Quel est le risque principal ?",o:["L'anoxie (CO2 et autres gaz)","L'électrocution","L'hypothermie","La noyade"],e:"La fermentation du grain produit du CO2. Engagement sous ARI avec détection (GDO Interventions dans les silos, 2019)."},
 {q:"Feu dans une cellule de silo : pourquoi éviter d'arroser abondamment ?",o:["Le grain gonfle et prend en masse, alourdit la cellule et peut la faire éclater","L'eau attise le feu de grain","Le grain devient explosif mouillé","Cela pollue la récolte"],e:"Trop d'eau rend aussi l'inertage délicat, voire inopérant. On privilégie souvent l'inertage (azote, CO2) en cellule fermée (GDO Silos 2019)."},
 {q:"Stock de fourrage : à partir de quelle température l'auto-échauffement peut-il tourner à l'auto-combustion ?",o:["70 °C","30 °C","45 °C","150 °C"],e:"La température normale de fermentation à cœur est d'environ 45 °C. À partir de 70 °C, la bascule vers l'auto-combustion est possible à tout moment (GDO Milieu agricole, 2019)."},
 {q:"Fosse à lisier : quel gaz dangereux, plus lourd que l'air, sent l'œuf pourri ?",o:["L'hydrogène sulfuré (H2S)","Le méthane","Le monoxyde de carbone","L'azote"],e:"L'H2S s'accumule en point bas. La détection gaz est indispensable avant tout engagement en fosse ou excavation (GDO Milieu agricole 2019)."},
 {q:"Les ammonitrates (engrais) en cas d'incendie :",o:["Sont comburants et peuvent détonner s'ils sont contaminés","Sont ininflammables et sans danger","Éteignent le feu","Ne dégagent aucun gaz"],e:"Les ammonitrates à plus de 80 % de nitrate d'ammonium peuvent détonner s'ils sont contaminés (matières organiques, hydrocarbures…). Leur décomposition dégage des gaz toxiques (GDO Milieu agricole 2019)."},
 {q:"Dans le Var, comment distinguer une vipère d'une couleuvre ?",o:["La vipère a une pupille verticale, la couleuvre une pupille ronde","La vipère est toujours plus grande","La couleuvre a un museau pointu","Seule la vipère siffle"],e:"La vipère a aussi un museau pointu et de petites écailles nombreuses sur la tête. Les serpents sont protégés, et on ne transporte jamais un animal mort : risque de morsure réflexe (SDIS 83, Risque animalier)."},
 {q:"Un câble électrique est tombé au sol : dans quel rayon empêcher quiconque d'approcher ?",o:["10 m","2 m","50 m","1 m"],e:"Ne pas s'approcher du conducteur et empêcher quiconque de le faire dans un rayon de 10 m (GDO Opérations de secours en présence d'électricité 2024)"},
 {q:"Quelle tension transporte le réseau HTB ?",o:["De 63 000 à 400 000 V","De 230 à 400 V","De 3 000 à 20 000 V","Plus de 1 000 000 V"],e:"Le réseau HTB (RTE) transporte de 63 kV à 400 kV ; le réseau HTA de distribution est généralement en 20 000 V (GDO Opérations de secours en présence d'électricité 2024)"},
 {q:"Quelle est la tension du réseau BT entre phases ?",o:["400 V","230 V","20 000 V","12 V"],e:"BT : 400 V entre phases, 230-240 V entre phase et neutre (GDO Opérations de secours en présence d'électricité 2024)"},
 {q:"Conseil à un requérant face à un incendie sur un ouvrage électrique :",o:["Ne pas projeter d'eau, couper le disjoncteur s'il est accessible","Arroser au tuyau d'arrosage","Toucher le câble pour vérifier","Monter sur le poteau"],e:"Ne pas tenter d'éteindre sans danger réel, ne pas projeter d'eau, couper le disjoncteur si accessible (GDO Opérations de secours en présence d'électricité 2024)"},
 {q:"Feu dans un silo : quels sont les deux points à ne jamais perdre de vue ?",o:["Pas d'eau dans le grain, pas de poussière en suspension","Ventiler à fond et arroser","Ouvrir toutes les trappes","Entrer dans la cellule rapidement"],e:"Pas d'eau directement dans le stockage de grain ; pas de poussière en suspension (explosion) (GDO Interventions dans les silos 2019)"},
 {q:"Quel périmètre d'exclusion réflexe autour d'un silo vertical ?",o:["50 m","25 m","10 m","200 m"],e:"Réflexe : 25 m pour un silo plat, 50 m pour un silo vertical ; ensuite 1,5 × la hauteur de l'installation (GDO Interventions dans les silos 2019)"},
 {q:"Quel périmètre d'exclusion réflexe autour d'un silo plat ?",o:["25 m","50 m","5 m","100 m"],e:"Silo plat : 25 m en réflexe (GDO Interventions dans les silos 2019)"},
 {q:"Quelle part des feux d'installations de silos concerne les séchoirs ?",o:["Environ 40 %","Environ 5 %","Environ 90 %","Aucun"],e:"40 % des feux dans ces installations concernent les séchoirs (GDO Interventions dans les silos 2019)"},
 {q:"Lors d'un inertage de silo, peut-on entrer dans la cellule ?",o:["Non","Oui, avec un ARI","Oui, après 10 minutes","Oui, si l'oxymètre est bon"],e:"En inertage : ne pas s'introduire dans les cellules, ne pas ouvrir d'orifices, suivi à l'oxymètre (GDO Interventions dans les silos 2019)"},
 {q:"Pour lutter contre un feu à cœur par inertage, quel taux d'oxygène viser ?",o:["Si possible moins de 8 %","Moins de 21 %","Plus de 15 %","Exactement 19,5 %"],e:"Le taux d'oxygène doit être si possible inférieur à 8 % ; l'azote injecté ne doit pas être liquide (GDO Interventions dans les silos 2019)"},
 {q:"Sinistre dans un silo : la coupure de l'électricité doit être :",o:["Partielle","Totale et immédiate","Interdite","Faite par les SP sur le TGBT"],e:"La coupure de l'électricité ne doit être que partielle (garder ventilation, vidange, etc.) (GDO Interventions dans les silos 2019)"},
 {q:"Au-delà de quelle teneur en eau un grain risque-t-il de fermenter et chauffer ?",o:["15 %","2 %","50 %","80 %"],e:"La fermentation est souvent le cas si la teneur en eau est supérieure à 15 % (GDO Interventions dans les silos 2019)"},
 {q:"Incendie de stockage d'ammonitrates : quel périmètre de zone contrôlée ?",o:["100 m (fumées toxiques)","10 m","1 km","20 m"],e:"Faire réaliser une zone contrôlée de 100 m de rayon en raison des fumées toxiques (GDO Interventions en milieu agricole 2019)"},
 {q:"Qu'est-ce qu'un ammonitrate « haut dosage » ?",o:["Plus de 80 % de nitrate d'ammonium","Moins de 10 % d'azote","Un engrais organique","Un engrais liquide sous pression"],e:"Haut dosage = plus de 80 % de nitrate d'ammonium (28 à 33 % d'azote) ; il peut détonner s'il est contaminé (GDO Interventions en milieu agricole 2019)"},
 {q:"Intervention sur une installation de méthanisation : où stationner les engins ?",o:["À 100 m de l'installation au moins","Au pied du digesteur","À 10 m","Sur la fosse"],e:"Porter EPI et ARI, stationner à 100 m au moins, se munir d'un détecteur multigaz (GDO Interventions en milieu agricole 2019)"},
 {q:"En présence d'animaux d'élevage, que limiter à l'arrivée ?",o:["L'emploi du deux-tons","L'éclairage de la scène","Le nombre de lances","Les communications radio"],e:"Limiter le deux-tons pour ne pas ajouter au stress des bêtes et établir un périmètre de sécurité (GDO Interventions en milieu agricole 2019)"},
 {q:"Sous quelle forme le butane et le propane sont-ils stockés dans les bouteilles ?",o:["Liquide","Gazeuse","Solide","Dissous dans l'acétone"],e:"Dans les bouteilles, butane et propane sont stockés sous forme liquide (gazeux à 15 °C et 1 bar) (GDO Interventions en présence de gaz 2021)"},
 {q:"Feu au robinet d'une bouteille de GPL : la fermeture du robinet peut-elle provoquer un retour de flamme dans la bouteille ?",o:["Non","Oui, toujours","Oui, si la bouteille est pleine","Oui, si elle est couchée"],e:"La fermeture du robinet ne peut pas entraîner un retour de flamme à l'intérieur de la bouteille (GDO Interventions en présence de gaz 2021)"},
 {q:"À partir de quelle température l'acétylène peut-il se décomposer spontanément dans sa bouteille ?",o:["65 °C","20 °C","150 °C","500 °C"],e:"La décomposition spontanée intervient dès qu'une bouteille d'acétylène dépasse 65 °C (GDO Interventions en présence de gaz 2021)"},
 {q:"En dessous de quel taux d'oxygène est-il interdit de travailler sans ARI ?",o:["19 %","10 %","15 %","21 %"],e:"Interdit de travailler dans une atmosphère à moins de 19 % d'oxygène sans ARI (GDO Interventions en présence de gaz 2021)"},
 {q:"Une bouteille de gaz munie d'une soupape peut-elle faire un BLEVE ?",o:["Oui, les dispositifs peuvent se déclencher trop tard","Non, jamais","Seulement si elle est en composite","Seulement si elle est vide"],e:"Un BLEVE peut survenir même si la bouteille a un dispositif de sécurité (disque, soupape) (GDO Interventions en présence de gaz 2021)"},
 {q:"Quel signe annonce qu'une bouteille de gaz a été exposée à la chaleur ?",o:["Fumées noires qui s'en échappent, étiquettes brûlées","Bouteille froide au toucher","Givre sur le robinet","Aucun signe visible n'existe"],e:"Fumées noires qui s'échappent de la bouteille, étiquettes brûlées, etc. doivent alerter (GDO Interventions en présence de gaz 2021)"},
 {q:"Quel est le rôle de GRDF ?",o:["Gestionnaire du réseau de distribution de gaz naturel","Transport du gaz haute pression","Fournisseur de bouteilles de butane","Contrôle des chaudières"],e:"GRDF est le gestionnaire du réseau de distribution (GRD) de gaz naturel ; GRTgaz gère le transport (GDO Interventions en présence de gaz 2021)"},
 {q:"De combien se dilate une bouteille de gaz « composite » ?",o:["Très faiblement (2 à 3 %)","Autant qu'une bouteille acier","De 50 %","Elle ne se dilate pas du tout"],e:"À l'inverse des bouteilles traditionnelles, les bouteilles composites ne se dilatent que de 2 à 3 % (GDO Interventions en présence de gaz 2021)"},
 {q:"Quel odorisant est encore utilisé pour le gaz en bouteille ?",o:["Le mercaptan","Le THT","L'ammoniac","Aucun"],e:"Le mercaptan (méthanethiol) est encore utilisé pour odoriser le gaz en bouteille ; le réseau utilise le THT (GDO Interventions en présence de gaz 2021)"},
 {q:"Fuite d'hydrogène de 4 mm à 200 bar : quel bruit à 1,50 m ?",o:["Environ 130 dB (avion au décollage)","Environ 40 dB","Aucun bruit","Environ 70 dB"],e:"Une telle fuite produit environ 130 dB à 1,50 m : protection auditive indispensable (GDO Interventions en présence de gaz 2021)"}
],
sr:[
 {q:"En arrivant sur un accident de la route, quelle est la première priorité ?",o:["Protéger la zone (positionnement de l'engin, balisage)","Désincarcérer immédiatement","Photographier la scène","Déplacer les véhicules"],e:"Sans protection, tout le monde est exposé au sur-accident."},
 {q:"À quoi sert le calage d'un véhicule accidenté ?",o:["Le stabiliser pour éviter des mouvements qui aggraveraient les lésions","Faciliter le remorquage","Empêcher la fuite de carburant","Protéger les pneus"],e:"Calage et stabilisation précèdent la création d'espace."},
 {q:"Règle des 30-60-90 : quelle distance face à un airbag conducteur non déclenché ?",o:["60 cm","30 cm","90 cm","10 cm"],e:"30 cm latéral, 60 cm conducteur, 90 cm passager. Vérifie la règle enseignée dans ton SDIS."},
 {q:"Sur un véhicule électrique ou hybride, de quelle couleur sont les câbles haute tension ?",o:["Orange","Bleu","Vert","Noir"],e:"On n'y coupe jamais. Neutraliser le véhicule et suivre la fiche d'aide à la décision du constructeur."},
 {q:"Quel outil hydraulique sert à sectionner un montant ?",o:["La cisaille","L'écarteur","Le vérin","Le coussin de levage"],e:"Cisaille : couper. Écarteur : écarter, ouvrir. Vérin : pousser."},
 {q:"Dès l'accès à une victime traumatisée dans un véhicule :",o:["Maintien de la tête en position neutre","On la sort par la vitre","On lui fait tourner la tête","On attend la fin de la désincarcération"],e:"Le maintien tête protège le rachis cervical jusqu'à l'immobilisation complète."},
 {q:"Avant de briser une vitre proche d'une victime :",o:["Protéger la victime et la prévenir","Ouvrir le toit","Retirer la ceinture","Couper la batterie à la cisaille"],e:"Protection (bâche, couverture), information, puis bris contrôlé."},
 {q:"Que signifie VSR ?",o:["Véhicule de secours routier","Véhicule de sauvetage rapide","Véhicule de soutien régional","Véhicule de secours et de réanimation"],e:"Il transporte le matériel de désincarcération, calage et balisage."},
 {q:"Dans quel ordre se déroule une opération de secours routier ?",o:["Protection et reconnaissance, calage, accès et bilan, création d'espace, extraction","Extraction, calage, bilan, protection","Création d'espace, protection, bilan, extraction","Bilan, extraction, protection, calage"],e:"La victime est prise en charge dès l'accès ; la création d'espace s'adapte à son état."},
 {q:"Sur un balisage routier, à quoi sert la zone tampon ?",o:["À permettre à un véhicule qui n'a pas vu la signalisation de s'arrêter avant le premier engin","À stocker le matériel de désincarcération","À regrouper les victimes","À stationner les véhicules des témoins"],e:"Ordre des zones : approche (pré-signalisation), tampon, puis travail. La zone tampon limite le risque de sur-accident (GDO Secours en milieu routier, 2025)."},
 {q:"Qu'est-ce qu'un sur-accident ?",o:["Un accident qui vient aggraver un accident déjà produit","Un accident avec plus de trois véhicules","Un accident sur autoroute","Un accident avec matières dangereuses"],e:"Le sur-accident est l'un des principaux risques pour les sapeurs-pompiers sur la route (GDO Secours routier 2025)."},
 {q:"Feu de véhicule : quel zonage a priori ?",o:["50 mètres","10 mètres","200 mètres","500 mètres"],e:"Pour un feu de véhicule, le zonage a priori est fixé à 50 m (GDO Secours routier 2025)."},
 {q:"Comment immobiliser un véhicule accidenté ?",o:["Couper le contact, frein de parc, levier sur P, caler les roues","Ouvrir toutes les portières","Débrancher la batterie haute tension","Dégonfler les pneus"],e:"Arrêt moteur (contact coupé, frein de parc, position P), calage des roues, voire amarrage dans l'axe le plus menaçant (GODR Interventions d'urgence sur les véhicules)."},
 {q:"Le véhicule a une clé « mains libres » (smart key). Que fais-tu ?",o:["Je l'éloigne à au moins 5 mètres du véhicule","Je la laisse sur le tableau de bord","Je la garde dans ma poche près du véhicule","Je la casse"],e:"Une smart key proche peut laisser le véhicule « prêt » : on l'éloigne à 5 m (GDO Secours routier 2025, GODR)."},
 {q:"D'après le GDO, quelle action rend le système airbag inerte ?",o:["Couper le contact ou débrancher la batterie 12 V","Ouvrir les portières","Couper la ceinture","Briser le pare-brise"],e:"Couper le contact ou débrancher la batterie 12 V rend le système airbag inerte. On garde les distances de sécurité tant que ce n'est pas fait (GDO Secours routier 2025)."},
 {q:"Jusqu'à quelle tension peut monter le système haute tension d'un véhicule électrique ou hybride ?",o:["800 V","48 V","230 V","20 000 V"],e:"Les systèmes HT peuvent aller jusqu'à 800 V. Ils comprennent batterie HT, convertisseur, moteur électrique, compresseur de clim, câbles HT… (GDO Secours routier 2025)."},
 {q:"Où trouver l'emplacement de la batterie haute tension d'un véhicule ?",o:["Sur sa fiche d'aide à la décision (fiche de sauvetage)","Sur la carte grise","Dans le carnet d'entretien","Sur la plaque d'immatriculation"],e:"La FAD du modèle indique l'emplacement de la batterie HT et le protocole de mise en sécurité. Sans elle, pas de manipulation du service plug (GDO Secours routier 2025)."},
 {q:"Quels signes évoquent l'emballement thermique d'une batterie ?",o:["Crépitements, bruit de torchère, épaississement des fumées, changement de couleur des flammes","Odeur d'œuf pourri uniquement","Klaxon qui se déclenche","Pneus qui éclatent"],e:"L'emballement dégage aussi des gaz toxiques (fluorure d'hydrogène, acide chlorhydrique…). La combustion d'une batterie peut durer plusieurs heures (GDO Secours routier 2025)."},
 {q:"Batterie HT en emballement après extinction de l'habitacle. Comment l'éteindre ?",o:["À l'eau, par le dispositif prévu par le constructeur (fireman access, trappe thermo-fusible)","En perçant le boîtier avec un outil de forcement","À la poudre uniquement","En la laissant brûler sans surveillance"],e:"On fait entrer l'eau dans la batterie par les dispositifs constructeur ou par les déformations, mais jamais en ouvrant le boîtier avec un outil (GDO Secours routier 2025)."},
 {q:"Particularité d'une flamme d'hydrogène ?",o:["Elle est invisible à l'œil nu de jour","Elle est toujours bleue et très visible","Elle produit une épaisse fumée noire","Elle ne dégage pas de chaleur"],e:"Sans poussières ni fumées, la flamme d'hydrogène ne se voit pas de jour. La caméra thermique aide à la repérer (GDO Secours routier 2025)."},
 {q:"Pourquoi un réservoir de GPL n'est-il rempli qu'à 80 % ?",o:["Pour absorber la dilatation du liquide avec la chaleur","Pour réduire le poids","Pour économiser le carburant","Pour éviter le gel"],e:"Le volume du GPL augmente d'environ 0,25 % par degré : les réservoirs ne sont remplis qu'à 80 % (GDO Secours routier 2025)."},
 {q:"BLEVE d'un réservoir de GPL de 50 L : jusqu'où les éclats peuvent-ils être projetés ?",o:["Jusqu'à 100 mètres","Jusqu'à 5 mètres","Jusqu'à 20 mètres","Jusqu'à 1 kilomètre"],e:"Éclats jusqu'à 100 m, boule de feu jusqu'à 30 m de diamètre pendant 3 secondes, plus un effet de surpression (GDO Secours routier 2025)."},
 {q:"Comment se brise une vitre en verre trempé ?",o:["En petits morceaux","En grands éclats coupants retenus par un film","Elle ne se brise pas","Elle fond"],e:"Le verre trempé (vitres latérales) se brise en petits morceaux. Le verre feuilleté (pare-brise) contient un film plastique et se découpe (GODR)."},
 {q:"Pendant une désincarcération, où ne faut-il jamais poser de matériel ?",o:["Sur le capot du véhicule accidenté","Sur une bâche au sol","Dans le parc matériel","Sur le plan de dépose"],e:"Ni matériel ni calage sur le capot : les capots actifs et les déformations peuvent bouger (GODR)."},
 {q:"Quel élément d'un véhicule ne doit-on jamais couper ?",o:["Un vérin de hayon ou de capot","Un montant B","Une ceinture de sécurité","Une branche de volant"],e:"Un vérin sous pression peut être projeté (effet missile), notamment en cas d'incendie (GODR)."},
 {q:"Accident sur autoroute : qui décide de la réouverture de la circulation ?",o:["Pas les pompiers : ils ne se prononcent jamais sur la réouverture","Le chef d'agrès du VSR","Le premier pompier arrivé","Le conducteur du FPT"],e:"Les secours peuvent nettoyer la chaussée en sécurité, mais ne se prononcent jamais sur la réouverture au trafic (GDO Secours routier 2025)."},
 {q:"Un témoin appelle pour un accident, circulation neutralisée. Quel conseil lui donne-t-on ?",o:["Mettre un gilet haute visibilité, ne pas bouger la victime, la rassurer et lui maintenir la tête","Sortir la victime du véhicule","Lui donner à boire","Retirer son casque si c'est un motard"],e:"Conseils au requérant : gilet haute visibilité, ne pas bouger la victime, la rassurer, la couvrir, maintenir la tête (GDO Secours routier 2025)."},
 {q:"Quelle hauteur libre sous un pont d'autoroute ?",o:["4,75 m","4,30 m","3,50 m","5,50 m"],e:"4,75 m sous les ponts d'autoroute, contre 4,30 m sur le reste du réseau (GDO Opérations de secours en milieu routier 2025)"},
 {q:"À partir de quelle longueur un tunnel présente-t-il des risques particuliers pour la sécurité ?",o:["300 m","100 m","1 km","50 m"],e:"Les tunnels de plus de 300 m sont des ouvrages à risques particuliers (GDO Opérations de secours en milieu routier 2025)"},
 {q:"Quelle vitesse peut atteindre un mur de fumée dans un tunnel ?",o:["Plus de 10 km/h","1 km/h maximum","Plus de 100 km/h","Il reste immobile"],e:"La vitesse du mur de fumée peut dépasser 10 km/h (14,4 km/h au Mont-Blanc) (GDO Opérations de secours en milieu routier 2025)"},
 {q:"Tunnel bitube : où mène-t-on les reconnaissances en priorité ?",o:["Dans le tube sinistré","Dans le tube sain","Dans les deux à égalité","Uniquement à l'extérieur"],e:"En tunnel bitube, les reconnaissances sont menées prioritairement dans le tube sinistré (GDO Opérations de secours en milieu routier 2025)"},
 {q:"Quelles informations recueillir auprès d'un appelant pour un accident en tunnel ?",o:["Nom du tunnel, sens de circulation, PK ou numéro d'abri","Uniquement la couleur des véhicules","L'heure d'ouverture du tunnel","Le nom de l'exploitant"],e:"Recueillir le nom du tunnel, le sens et le point kilométrique / n° d'abri ou de garage (GDO Opérations de secours en milieu routier 2025)"},
 {q:"À quelle pression sont stockés les réservoirs d'un véhicule à hydrogène ?",o:["350 à 700 bar","10 à 20 bar","200 à 300 bar","1 000 à 2 000 bar"],e:"Les véhicules à pile à combustible ont des réservoirs d'hydrogène de 350 à 700 bar (GDO Opérations de secours en milieu routier 2025)"},
 {q:"De quelle couleur peuvent être certaines canalisations d'hydrogène haute pression ?",o:["Rouge","Orange","Vert","Jaune"],e:"Certaines canalisations H2 haute pression peuvent être rouges (le orange désigne les câbles HT) (GDO Opérations de secours en milieu routier 2025)"},
 {q:"Quel type de verre est obligatoire pour un pare-brise ?",o:["Le verre feuilleté","Le verre trempé","Le plexiglas","Le verre armé"],e:"Le verre feuilleté est obligatoire pour les pare-brise ; les vitres latérales sont souvent en verre trempé (GDO Opérations de secours en milieu routier 2025)"},
 {q:"Pour éteindre une batterie HT, peut-on ouvrir son casing avec un outil de forcement ?",o:["Non, jamais","Oui, c'est la méthode recommandée","Oui, avec une disqueuse","Oui, si la batterie est froide"],e:"On cherche à faire entrer l'eau par les déformations ou parties fondues, jamais en ouvrant le casing avec un outil (GDO Opérations de secours en milieu routier 2025)"},
 {q:"Peut-on engager du personnel dans un véhicule instable ?",o:["Non, pas avant stabilisation ou arrimage total","Oui, si la victime est grave","Oui, avec un casque","Oui, par le hayon arrière"],e:"Aucun engagement dans un véhicule instable tant qu'il n'est pas stabilisé ou arrimé totalement (GDO Opérations de secours en milieu routier 2025)"},
 {q:"Quelle tension a la batterie de servitude classique d'un véhicule ?",o:["12 V","48 V","230 V","400 V"],e:"Les véhicules sont équipés généralement d'une batterie au plomb de 12 V (GDO Opérations de secours en milieu routier 2025)"},
 {q:"Que signifie le carburant E10 ?",o:["Essence SP95 contenant jusqu'à 10 % de bioéthanol","Gazole avec 10 % d'EMAG","Essence à 10 % de plomb","Électrique 10 kWh"],e:"E10 = SP95 enrichi à 10 % de bioéthanol ; B10 = gazole jusqu'à 10 % d'EMAG ; E85 = superéthanol (GDO Opérations de secours en milieu routier 2025)"},
 {q:"Semi-remorque d'hydrogène en fuite ou en feu : que fait-on ?",o:["On n'intervient pas dessus, sauf dégagement de personne nécessaire","On l'attaque immédiatement à la lance","On ferme les vannes sans protection","On déplace la remorque"],e:"Ne pas intervenir sur la semi-remorque en cas de fuite H2 ou de feu, sauf dégagement nécessaire, et établir une zone d'exclusion (GDO Opérations de secours en milieu routier 2025)"},
 {q:"Qu'est-ce que le « pistonnement » dans un tunnel ?",o:["L'effet des véhicules en mouvement qui pousse l'air","Une technique de désincarcération","Le bruit des ventilateurs","Le démarrage d'un moteur"],e:"Le pistonnement est l'effet des véhicules en mouvement sur l'écoulement de l'air (tunnels unidirectionnels) (GDO Opérations de secours en milieu routier 2025)"},
 {q:"Une fois le désenfumage d'un tunnel lancé, quand atteint-il son débit nominal ?",o:["Après quelques minutes","Instantanément","Après plusieurs heures","Jamais"],e:"Il faut compter quelques minutes pour atteindre le débit nominal (GDO Opérations de secours en milieu routier 2025)"}
],
fdf:[
 {q:"Quelle partie d'un feu de forêt avance le plus vite et est la plus dangereuse ?",o:["La tête","La queue","Les flancs","La lisière brûlée"],e:"On l'attaque rarement de face : on travaille sur les flancs à partir d'un point d'appui."},
 {q:"Les trois grands facteurs de propagation d'un feu de forêt sont :",o:["La météo, le relief et la végétation","La température, la pluie et l'heure","Les engins, l'eau et le vent","Le sol, les routes et la lune"],e:"Vent, humidité, température ; pente et exposition ; type et état de la végétation."},
 {q:"Un feu monte une pente. Sa vitesse :",o:["Augmente","Diminue","Ne change pas","S'annule"],e:"Les flammes préchauffent la végétation située au-dessus."},
 {q:"Qu'est-ce qu'une saute de feu ?",o:["Un foyer secondaire allumé en avant du front par des particules portées par le vent","Le retour du feu sur une zone brûlée","Un feu qui rampe sous une route","Un contre-feu volontaire"],e:"Les sautes peuvent prendre les équipes à revers."},
 {q:"Composition classique d'un GIFF ?",o:["4 CCF et un véhicule de chef de groupe","2 FPT et un VSAV","6 CCF sans encadrement","1 CCF et 1 VSR"],e:"La composition exacte suit l'ordre d'opération départemental."},
 {q:"L'obligation légale de débroussaillement (OLD) autour d'une construction s'applique en général sur :",o:["50 mètres","5 mètres","10 mètres","500 mètres"],e:"50 m, pouvant être porté à 100 m par arrêté."},
 {q:"Un CCF est menacé par le front de flammes. Que fait l'équipage ?",o:["Autoprotection : cabine, vitres fermées, rampes d'arrosage en fonction","Fuir à pied dans la végétation","Sortir attaquer la tête à la lance","Couper le moteur et attendre dehors"],e:"La manœuvre d'autoprotection doit devenir un réflexe."},
 {q:"Pourquoi partir d'un point d'appui pour attaquer ?",o:["Pour agir depuis une zone sûre sans être contourné","Pour économiser le carburant","Pour être plus près du centre du feu","Pour être visible des médias"],e:"Route, piste, zone brûlée… et toujours un itinéraire de repli."},
 {q:"Une faible hygrométrie de l'air :",o:["Rend la végétation plus inflammable","Ralentit le feu","N'a aucun effet","Empêche les sautes de feu"],e:"Air sec, vent fort et chaleur : risque très sévère."},
 {q:"Que signifie CCF ?",o:["Camion-citerne feux de forêt","Centre de commandement forestier","Colonne de combat feu","Camion de commandement de feu"],e:"Les CCF sont équipés pour l'autoprotection de l'équipage."},
 {q:"De quoi se compose une unité d'intervention feux de forêts (UIFF) ?",o:["2 CCF de classe M ou S","4 CCF et un VLHR","1 CCF et un FPT","3 GIFF"],e:"L'UIFF compte 2 CCF (M ou S). Renforcée d'un CCF de classe S, elle devient une ULIFF (GTO Feux de forêts, 2021)."},
 {q:"Une colonne d'intervention feux de forêts comprend au minimum :",o:["3 GIFF et un élément de commandement et de soutien","2 UIFF","4 CCF","10 CCF isolés"],e:"Colonne : 3 GIFF minimum + commandement et soutien, sous les ordres d'un chef de colonne FDF4 (GTO Feux de forêts 2021)."},
 {q:"Quelle formation doit avoir le chef d'un GIFF ?",o:["FDF 3","FDF 1","FDF 2","FDF 4"],e:"FDF 1 et 2 : équipiers et chefs d'agrès · FDF 3 : chef de groupe · FDF 4 : chef de colonne (GTO Feux de forêts 2021)."},
 {q:"Quelle est la masse totale en charge d'un CCF moyen (CCFM) ?",o:["Entre 7,5 et 14 tonnes","Moins de 3,5 tonnes","Entre 3 et 7,5 tonnes","Plus de 19 tonnes"],e:"CCFL : 3 à 7,5 t · CCFM : 7,5 à 14 t · CCFS : plus de 14 t. Ce classement ne reflète pas les capacités opérationnelles (GTO Feux de forêts 2021)."},
 {q:"Qu'appelle-t-on une « lance 500 » en feux de forêts ?",o:["Une lance à débit variable sur tuyau DN 45, jusqu'à 500 L/min","Une lance sur tuyau DN 25 à 150 L/min","Une lance-canon de 5 000 L/min","Une lance de 500 mètres de long"],e:"Lance 500 : DN 45, 500 L/min maximum · lance 150 : DN 25, 150 L/min maximum (GTO Feux de forêts 2021)."},
 {q:"À quoi sert une lance « queue de paon » ?",o:["À créer un rideau d'eau, notamment en autodéfense","À attaquer la tête du feu en jet droit","À remplir la citerne","À traiter les fumerolles"],e:"Sur DN 45 à 500 L/min, elle crée un écran d'environ 7 m de haut et 25 m de large (GTO Feux de forêts 2021)."},
 {q:"Vent moyen de 30 km/h. Vitesse de propagation estimée du feu ?",o:["Environ 0,9 km/h","Environ 3 km/h","Environ 10 km/h","Environ 30 km/h"],e:"Valeur empirique : environ 3 % de la vitesse du vent moyen. 3 % de 30 = 0,9 km/h (GDO Feux de forêts, 2021)."},
 {q:"En dessous de quelle hygrométrie de l'air le risque feu devient-il très fortement aggravé ?",o:["30 %","60 %","80 %","90 %"],e:"Sous 30 %, éclosion et propagation sont très fortement aggravées, sautes de feu comprises (GDO Feux de forêts 2021)."},
 {q:"Comment appelle-t-on la lisière qui se propage contre le vent ?",o:["L'arrière","La tête","Le flanc","La baie"],e:"Tête : poussée par le vent · flancs : lisières latérales · arrière : progresse contre le vent (GDO Feux de forêts 2021)."},
 {q:"Qu'est-ce qu'une rocade ?",o:["Un accès qui longe une lisière sans la traverser","Un accès qui traverse la lisière","Une zone débroussaillée","Une réserve d'eau DFCI"],e:"La pénétrante traverse une lisière ou la zone d'intervention, la rocade la longe ou en fait le tour (GDO Feux de forêts 2021)."},
 {q:"Qu'est-ce qu'une « baie » sur un feu de forêt ?",o:["Une partie de la lisière qui avance plus lentement (obstacle, pente défavorable…)","La partie la plus rapide du front","Une zone brûlée sûre","Un point d'eau naturel"],e:"La baie progresse plus lentement à cause d'obstacles, du combustible ou d'une pente défavorable (GDO Feux de forêts 2021)."},
 {q:"Qu'est-ce que le feu tactique ?",o:["Allumer un feu secondaire face à l'incendie pour lui retirer du combustible","Laisser brûler une zone sans intervenir","Éteindre le feu avec du retardant","Un feu d'exercice en caserne"],e:"Il sert aussi à canaliser un flanc, réaligner une lisière, créer une zone d'appui ou de repli (GTO Feux de forêts 2021)."},
 {q:"Qu'est-ce qu'un largage de sécurité ?",o:["Un largage délibéré sur un véhicule ou un groupe en difficulté pour abattre flammes et chaleur","Un largage sur la tête du feu","Un largage d'eau sur les habitations","Un largage annulé pour raison de sécurité"],e:"Il n'est demandé qu'en situation d'autodéfense, après accord du COS ou de l'AERO (en extrême urgence par le bénéficiaire) (GTO Feux de forêts 2021)."},
 {q:"Face à un événement brutal, quel est l'unique espace de survie de l'équipage d'un CCF ?",o:["La cabine du véhicule","Le dessous du véhicule","Une zone non brûlée sous le vent","La citerne"],e:"La cabine autoprotégée reste et restera toujours l'unique espace de survie (GTO Feux de forêts 2021)."},
 {q:"À l'arrêt sur un chantier, comment le conducteur positionne-t-il son CCF ?",o:["Dans le sens du départ, moteur tournant","Face au feu, moteur coupé","En travers de la piste","Le plus près possible des flammes"],e:"Sens du départ, moteur tournant, calé si besoin. Le conducteur veille la radio et la permanence de l'eau (GTO Feux de forêts 2021)."},
 {q:"Repli à la cabine impossible. Vers quelle zone te replies-tu ?",o:["Une zone pyro-résistante désignée : vignes, pierrier, zone déjà brûlée","Une zone de broussailles sous le vent","Le haut d'une pente","Un bosquet de pins"],e:"Le lieu de repli est indiqué avant toute action : vignes, pierrier, zone brûlée… (GTO Feux de forêts 2021)."},
 {q:"En autodéfense d'un groupe, où place-t-on le VLHR ?",o:["Entre les CCF, sans bloquer l'accès aux cabines","Devant le groupe, face au feu","Loin du groupe, en zone sûre","Derrière le dernier CCF, moteur coupé"],e:"Le chef de groupe resserre le dispositif, VLHR entre les CCF, et rassemble les équipages en cabine (GTO Feux de forêts 2021)."},
 {q:"Quelle pente maximale un CCF peut-il franchir (de face) ?",o:["50 %","30 %","70 %","100 %"],e:"La pente se franchit de face et ne doit pas dépasser 50 % pour un CCF (GTO Lutte contre les FDF et espaces naturels 2021)"},
 {q:"Quel dévers maximal un CCF peut-il supporter ?",o:["30 %","50 %","15 %","45 %"],e:"Le dévers ne doit pas dépasser 30 % pour un CCF (GTO Lutte contre les FDF et espaces naturels 2021)"},
 {q:"Quel écran crée une queue de paon 500 L/min alimentée en DN 45 ?",o:["Environ 7 m de haut sur 25 m de large","Environ 2 m de haut sur 5 m de large","Environ 20 m de haut sur 50 m de large","Environ 10 m de haut sur 30 m de large"],e:"Queue de paon DN 45 (500 L/min) : écran d'environ 7 m × 25 m ; en DN 70 (1 000 L/min) : 10 m × 30 m (GTO Lutte contre les FDF et espaces naturels 2021)"},
 {q:"Quelle autonomie offre une queue de paon DN 45 avec une citerne à moitié pleine ?",o:["6 minutes","20 minutes","1 minute","15 minutes"],e:"Une queue de paon DN 45 offre environ 6 minutes d'autonomie avec une citerne à moitié remplie (GTO Lutte contre les FDF et espaces naturels 2021)"},
 {q:"Quel débit maximal ont les lances alimentées en DN 25 en feux de forêts ?",o:["150 L/min","500 L/min","250 L/min","1 000 L/min"],e:"Lances DN 25 : 150 L/min max ; lances DN 45 (« lance 500 ») : 500 L/min max (GTO Lutte contre les FDF et espaces naturels 2021)"},
 {q:"Jusqu'à quelle distance un GIFF établit-il 4 lances 500 ?",o:["120 m","280 m","440 m","60 m"],e:"Établissements du groupe : 4 lances 500 à 120 m ; 2 lances 500 à 280 m ; 1 lance 500 (ou 2 × 150) à 440 m ; au-delà = grande longueur (GTO Lutte contre les FDF et espaces naturels 2021)"},
 {q:"Jusqu'à quelle distance un GIFF établit-il 2 lances 500 ?",o:["280 m","120 m","440 m","1 km"],e:"2 lances 500 jusqu'à 280 m (GTO Lutte contre les FDF et espaces naturels 2021)"},
 {q:"À partir de quelle longueur parle-t-on d'établissement de grande longueur (EGL) ?",o:["Au-delà de 440 m","Au-delà de 120 m","Au-delà de 1 km","Au-delà de 200 m"],e:"L'établissement supérieur à 440 m est dit de grande longueur et nécessite claies de portage, motopompes, etc. (GTO Lutte contre les FDF et espaces naturels 2021)"},
 {q:"Une UIFF (2 CCF) peut établir 1 lance 500 jusqu'à :",o:["120 m (ou 2 lances jusqu'à 60 m)","440 m","280 m","30 m"],e:"L'unité établit 1 lance 150/500 à 120 m ou 2 lances 150/500 à 60 m (GTO Lutte contre les FDF et espaces naturels 2021)"},
 {q:"Quelle distance de sécurité entre véhicules d'une colonne FDF sur route ?",o:["Environ 50 m","Environ 10 m","Environ 200 m","Environ 5 m"],e:"La distance de sécurité entre véhicules en déplacement sur route est d'environ 50 m (GTO Lutte contre les FDF et espaces naturels 2021)"},
 {q:"Quelle vitesse maximale pour un convoi FDF sur route (hors agglomération) ?",o:["60 km/h","80 km/h","90 km/h","50 km/h"],e:"Sur route : 60 km/h maximum et adaptée ; en agglomération : 50 km/h (GTO Lutte contre les FDF et espaces naturels 2021)"},
 {q:"Le guidage lors des manœuvres d'engins en feux de forêts est :",o:["Obligatoire","Conseillé seulement de nuit","Inutile pour un CCF","Réservé aux CCF super"],e:"Lors des manœuvres d'engins, le guidage est obligatoire (GTO Lutte contre les FDF et espaces naturels 2021)"},
 {q:"Quelle capacité d'eau minimale pour un CCF moyen (CCFM) ?",o:["1 500 L","600 L","5 000 L","3 000 L"],e:"CU minimales : CCFL 600 L, CCFM 1 500 L, CCFS 5 000 L (GTO Lutte contre les FDF et espaces naturels 2021)"},
 {q:"Quelle autonomie minimale du système d'air respirable de la cabine d'un CCF ?",o:["10 minutes pour 4 personnes (30 L/min chacune)","30 minutes pour 2 personnes","1 heure pour 4 personnes","2 minutes par personne"],e:"La cabine dispose d'un air respirable d'au moins 10 minutes pour 4 personnes à 30 L/min (GTO Lutte contre les FDF et espaces naturels 2021)"},
 {q:"L'appareil isolant d'évacuation (autonomie 6 min) peut-il servir à une reconnaissance ?",o:["Non, uniquement au repli ou au dégagement d'urgence","Oui, si elle dure moins de 6 minutes","Oui, pour un sauvetage","Oui, sur ordre du chef de groupe"],e:"Cet EPI est uniquement destiné au repli ou au dégagement d'urgence, jamais aux sauvetages ou reconnaissances (GTO Lutte contre les FDF et espaces naturels 2021)"},
 {q:"Lors d'un largage d'un bombardier d'eau, quelle zone évacuer ?",o:["40 m de part et d'autre de l'axe de largage","10 m autour du point d'impact","100 m devant l'avion","Aucune, on reste sous le largage"],e:"Quel que soit l'appareil, évacuer l'axe de largage sur 40 m de part et d'autre (GTO Lutte contre les FDF et espaces naturels 2021)"},
 {q:"Le CCF part se ravitailler au point d'eau. Que fait le porte-lance ?",o:["Il remonte obligatoirement dans la cabine","Il reste seul sur la lisière","Il suit à pied","Il attend sur le chemin"],e:"Le porte-lance remonte obligatoirement dans la cabine quand l'engin se rend au point d'eau (GTO Lutte contre les FDF et espaces naturels 2021)"},
 {q:"Quel linéaire de barrière de retardant un détachement peut-il poser en 1 heure ?",o:["1 km sur 6 m de large","100 m sur 1 m de large","10 km sur 20 m de large","500 m sur 2 m de large"],e:"Capacité : 1 km × 6 m en 1 h ; 80 000 L de retardant ≈ 2,7 km avant recomplètement (GTO Lutte contre les FDF et espaces naturels 2021)"},
 {q:"Quel front de feu un groupe (4 CCF) peut-il couvrir en attaque de front ?",o:["Environ 100 m","Environ 1 km","Environ 20 m","Environ 500 m"],e:"Distance couverte par le groupe : 320 m en jalonnement, 100 m en attaque de front (GTO Lutte contre les FDF et espaces naturels 2021)"}
],
cult:[
 {q:"Quel est le numéro d'appel d'urgence européen ?",o:["112","15","18","114"],e:"15 SAMU · 17 police/gendarmerie · 18 pompiers · 112 Europe · 114 personnes sourdes ou malentendantes."},
 {q:"Quel grade vient juste au-dessus de caporal ?",o:["Caporal-chef","Sergent","Sapeur de 1re classe","Adjudant"],e:"Caporal, caporal-chef, sergent, sergent-chef, adjudant, adjudant-chef."},
 {q:"Quel grade vient juste au-dessus de sergent-chef ?",o:["Adjudant","Lieutenant","Caporal-chef","Capitaine"],e:"Puis adjudant-chef, et les officiers : lieutenant, capitaine, commandant, lieutenant-colonel, colonel."},
 {q:"Quelle est la date de la Sainte-Barbe ?",o:["4 décembre","14 juillet","1er novembre","25 décembre"],e:"Patronne des sapeurs-pompiers."},
 {q:"Quelle est la devise des sapeurs-pompiers ?",o:["Courage et dévouement","Sauver ou périr","Honneur et patrie","Toujours prêts"],e:"« Sauver ou périr » est la devise de la BSPP."},
 {q:"Que signifie VSAV ?",o:["Véhicule de secours et d'assistance aux victimes","Véhicule de sauvetage et d'appui","Véhicule sanitaire d'aide aux victimes","Voiture de secours vitale"],e:"VSAV = véhicule de secours et d'assistance aux victimes, l'ambulance des sapeurs-pompiers (SSUAP)."},
 {q:"Que signifie FPT ?",o:["Fourgon pompe-tonne","Fourgon de protection technique","Fourgon pour transport","Fourgon polyvalent tout-terrain"],e:"FPT = fourgon pompe-tonne, engin d'incendie avec pompe et citerne."},
 {q:"Quel réseau radio des services de secours est remplacé progressivement par le RRF ?",o:["ANTARES","RUBIS","ACROPOL","GSM-R"],e:"Le Réseau Radio du Futur (RRF) succède à ANTARES."},
 {q:"Qui est le directeur des opérations de secours (DOS) sur sa commune ?",o:["Le maire","Le chef de centre","Le directeur du SDIS","Le chef d'agrès"],e:"Le préfet devient DOS si l'événement dépasse la commune ou s'il le décide. Le COS est un sapeur-pompier.",l:"spp av"},
 {q:"Qu'est-ce qu'un SDIS ?",o:["Un établissement public départemental","Un service de la préfecture","Une association loi 1901","Un service communal"],e:"Administré par un conseil d'administration (CASDIS), dirigé par un directeur départemental (DDSIS).",l:"spp av"},
 {q:"De quel ministère relève la DGSCGC ?",o:["Ministère de l'Intérieur","Ministère des Armées","Ministère de la Santé","Ministère de la Transition écologique"],e:"Direction générale de la sécurité civile et de la gestion des crises.",l:"spp av"},
 {q:"Quelle loi de novembre 2021 consolide le modèle de sécurité civile et le volontariat ?",o:["La loi Matras","La loi Pasqua","La loi NOTRe","La loi Évin"],e:"Loi du 25 novembre 2021.",l:"spp av"},
 {q:"Quelles unités de sapeurs-pompiers ont un statut militaire ?",o:["La BSPP et le BMPM","Tous les SDIS","Les volontaires","Aucune"],e:"Brigade de sapeurs-pompiers de Paris (Armée de terre), Bataillon de marins-pompiers de Marseille (Marine nationale).",l:"spp av"},
 {q:"Quelle est la durée de l'engagement d'un sapeur-pompier volontaire ?",o:["5 ans, renouvelable","1 an","10 ans","Sans durée"],e:"Renouvelable tacitement."},
 {q:"Quel engin est une échelle aérienne ?",o:["EPA","VTU","VLHR","CCF"],e:"Échelle pivotante automatique. VTU : véhicule tous usages."}
],
com:[
 {q:"Que signifie la méthode SOIEC ?",o:["Situation, Objectifs, Idée de manœuvre, Exécution, Commandement","Sécurité, Organisation, Intervention, Évacuation, Contrôle","Situation, Ordres, Intentions, Effectifs, Conclusions","Secours, Observation, Information, Engagement, Compte rendu"],e:"Trame de l'ordre initial, parfois complétée par la Logistique (SOIECL).",l:"av"},
 {q:"Quelle trame suit un message de renseignements ?",o:["Je suis, je vois, je prévois, je fais, je demande","Qui, quoi, où, quand, comment","Situation, mission, exécution, logistique","Alerte, départ, arrivée, retour"],e:"Situation, évolution, action engagée et besoins, en peu de mots.",l:"av"},
 {q:"Quel est le but du message d'ambiance ?",o:["Donner très tôt une idée de l'ampleur de l'intervention","Annoncer la fin de l'intervention","Demander le retour au centre","Informer la presse"],e:"Court, émis dès l'arrivée, il permet au CODIS d'anticiper.",l:"av"},
 {q:"Le chef d'agrès est responsable :",o:["De son engin, de son équipage et de la mission confiée","De tous les engins du groupe","De l'évacuation d'une commune","Du budget du centre"],e:"Il reconnaît, ordonne, rend compte et veille à la sécurité de son personnel.",l:"av"},
 {q:"Qui est le commandant des opérations de secours (COS) ?",o:["Un sapeur-pompier désigné, sous l'autorité du DOS","Le maire","Le préfet","Le médecin du SAMU"],e:"Le DOS (maire ou préfet) dirige les opérations ; le COS commande les moyens sur le terrain.",l:"spp av"},
 {q:"Que désigne le PRV ?",o:["Point de rassemblement des victimes","Poste radio de veille","Plan de reconnaissance des voies","Point de ravitaillement des véhicules"],e:"Lieu de regroupement, de tri et de prise en charge avant évacuation.",l:"av"},
 {q:"Pourquoi le chef d'agrès fait-il une reconnaissance avant d'engager ?",o:["Pour évaluer risques et victimes et choisir l'idée de manœuvre","Par obligation administrative","Pour attendre les renforts","Pour prendre des photos"],e:"La reconnaissance oriente toute la manœuvre.",l:"av"}
],
fr:[
{q:"« Les victimes que nous avons ___ ont été transportées. »",o:["secourues","secourus","secouru","secourut"],e:"Avec avoir, le participe passé s'accorde avec le COD placé avant : « que » reprend « les victimes » (féminin pluriel).",l:"spp"},
{q:"« Ils ont ___ toute la nuit. » (travailler)",o:["travaillé","travaillés","travailler","travaillait"],e:"Avec avoir et sans COD placé avant, le participe passé reste invariable.",l:"spp"},
{q:"« Les pompiers sont ___ rapidement. » (arriver)",o:["arrivés","arrivé","arriver","arrivées"],e:"Avec être, le participe passé s'accorde avec le sujet (masculin pluriel).",l:"spp"},
{q:"« Elles se sont ___ en descendant l'échelle. » (blesser)",o:["blessées","blessé","blessés","blesser"],e:"Verbe pronominal : « se » est COD (elles ont blessé elles-mêmes), placé avant, donc accord.",l:"spp"},
{q:"Complète : « Il ___ parti ___ la caserne. »",o:["est / à","et / à","est / a","et / a"],e:"« est » : on peut dire « était ». « à » préposition : on ne peut pas dire « avait ».",l:"spp"},
{q:"Complète : « ___ un départ urgent. »",o:["C'est","S'est","Ces","Ses"],e:"« C'est » = cela est. « S'est » s'emploie devant un participe passé (il s'est blessé).",l:"spp"},
{q:"Complète : « Nous ne savons pas ___ se trouve la victime. »",o:["où","ou","oû","ous"],e:"« où » indique le lieu ; « ou » signifie « ou bien ».",l:"spp"},
{q:"Complète : « Il faut ___ la zone. »",o:["baliser","balisé","balisez","balisait"],e:"Après « il faut », on met l'infinitif. Astuce : remplace par « vendre » (il faut vendre).",l:"spp"},
{q:"Complète : « Je ___ appelé les secours. »",o:["ai","est","es","et"],e:"Passé composé avec avoir : j'ai appelé.",l:"spp"},
{q:"Complète : « Je ___ ai donné les consignes. » (à eux)",o:["leur","leurs","leurent","l'heure"],e:"Devant un verbe, « leur » est un pronom et ne prend jamais de s.",l:"spp"},
{q:"Complète : « Le véhicule ___ la porte est ouverte. »",o:["dont","que","où","qui"],e:"« dont » remplace un complément introduit par « de » : la porte du véhicule.",l:"spp"},
{q:"Complète : « ___ tu fasses, reste prudent. »",o:["Quoi que","Quoique","Quoiqu'","Quoi-que"],e:"« Quoi que » (en deux mots) = quelle que soit la chose que. « Quoique » (en un mot) = bien que.",l:"spp"},
{q:"Complète : « Il faut que tu ___ prudent. » (être)",o:["sois","es","soit","serais"],e:"« Il faut que » appelle le subjonctif : que tu sois (« soit » est la 3e personne).",l:"spp"},
{q:"Complète : « Demain, nous ___ en manœuvre. » (aller, futur)",o:["irons","allerons","irions","allions"],e:"Futur de aller : j'irai, tu iras, il ira, nous irons, vous irez, ils iront.",l:"spp"},
{q:"Complète : « Si j'avais le temps, je ___ t'aider. » (venir)",o:["viendrais","viendrai","venais","viendrait"],e:"Si + imparfait entraîne le conditionnel présent : je viendrais.",l:"spp"},
{q:"Imparfait de « crier » avec « nous » :",o:["nous criions","nous crions","nous criyons","nous crièrent"],e:"Imparfait : radical cri- + -ions, d'où deux i (« nous crions » est le présent).",l:"spp"},
{q:"Quel mot est correctement orthographié ?",o:["nécessaire","nécéssaire","nécesaire","néssessaire"],e:"Un seul accent, un c, deux s.",l:"spp"},
{q:"Pluriel de « un travail » :",o:["des travaux","des travails","des travailles","des travaus"],e:"Les noms en -ail font souvent leur pluriel en -aux : travail, corail, émail, vitrail…",l:"spp"},
{q:"Pluriel de « un pneu » :",o:["des pneus","des pneux","des pneu","des pneues"],e:"Exceptions des noms en -eu qui prennent un s : pneu, bleu, émeu.",l:"spp"},
{q:"Complète : « des gilets ___ » (marron)",o:["marron","marrons","marronnes","marronnés"],e:"Les adjectifs de couleur issus d'un nom (marron, orange, cerise…) restent invariables. Exceptions : rose, mauve, fauve, pourpre.",l:"spp"},
{q:"Dans « Il court vite », le mot « vite » est :",o:["un adverbe","un adjectif","un verbe","un nom"],e:"Il modifie le verbe « court » et ne s'accorde pas.",l:"spp"},
{q:"Que signifie « imminent » ?",o:["Qui va se produire très bientôt","Qui est très important","Qui est dangereux","Qui s'est déjà produit"],e:"Ne pas confondre avec « éminent » (remarquable, important).",l:"spp"},
{q:"Quel est le synonyme de « prompt » ?",o:["rapide","lent","prudent","brutal"],e:"Un prompt rétablissement = un rétablissement rapide.",l:"spp"},
{q:"Quel est le contraire de « ascendant » ?",o:["descendant","montant","croissant","adjacent"],e:"Ascendant : qui monte ; descendant : qui descend.",l:"spp"}
],
math:[
{q:"Une lance débite 500 L/min pendant 12 min. Quelle quantité d'eau a-t-elle utilisée ?",o:["6 000 L","600 L","5 120 L","60 000 L"],e:"Quantité = débit × durée = 500 × 12 = 6 000 L.",l:"spp"},
{q:"Un engin a une réserve de 3 000 L et alimente une lance à 250 L/min. Quelle est son autonomie ?",o:["12 min","10 min","15 min","7 min 30 s"],e:"Autonomie = volume ÷ débit = 3 000 ÷ 250 = 12 min.",l:"spp"},
{q:"Combien de litres dans 1 m³ ?",o:["1 000 L","100 L","10 000 L","10 L"],e:"1 m³ = 1 000 dm³ et 1 dm³ = 1 L.",l:"spp"},
{q:"60 m³/h correspondent à :",o:["1 000 L/min","600 L/min","100 L/min","3 600 L/min"],e:"60 m³/h = 60 000 L ÷ 60 min = 1 000 L/min.",l:"spp"},
{q:"Pour 1 000 L de solution moussante dosée à 3 %, combien faut-il d'émulseur ?",o:["30 L","3 L","300 L","33 L"],e:"3 % de 1 000 L = 1 000 × 3 ÷ 100 = 30 L.",l:"spp"},
{q:"Une bouteille d'ARI de 6 L gonflée à 300 bar contient environ :",o:["1 800 L d'air","306 L d'air","50 L d'air","18 000 L d'air"],e:"Volume d'air détendu ≈ capacité × pression = 6 × 300 = 1 800 L (approximation).",l:"spp"},
{q:"Combien font 15 % de 240 ?",o:["36","24","32","40"],e:"240 × 15 ÷ 100 = 36 (10 % = 24, 5 % = 12).",l:"spp"},
{q:"Un article à 80 € augmente de 25 %. Nouveau prix ?",o:["100 €","105 €","95 €","120 €"],e:"80 × 1,25 = 100 €.",l:"spp"},
{q:"Après une baisse de 20 %, un article coûte 64 €. Quel était son prix ?",o:["80 €","76,80 €","84 €","78 €"],e:"Prix × 0,8 = 64, donc prix = 64 ÷ 0,8 = 80 €. Ajouter 20 % à 64 € est un piège.",l:"spp"},
{q:"Dans un centre de 40 sapeurs-pompiers, 10 sont professionnels. Quel pourcentage ?",o:["25 %","40 %","10 %","4 %"],e:"10 ÷ 40 = 0,25 = 25 %.",l:"spp"},
{q:"Un engin parcourt 45 km en 30 min. Sa vitesse moyenne est :",o:["90 km/h","45 km/h","75 km/h","135 km/h"],e:"30 min = 0,5 h ; v = 45 ÷ 0,5 = 90 km/h.",l:"spp"},
{q:"Combien de temps pour parcourir 12 km à 80 km/h ?",o:["9 min","15 min","6 min","12 min"],e:"t = 12 ÷ 80 = 0,15 h = 0,15 × 60 = 9 min.",l:"spp"},
{q:"2,5 h correspondent à :",o:["2 h 30 min","2 h 50 min","2 h 25 min","2 h 05 min"],e:"0,5 h = 30 min. Ne pas lire les décimales d'heure comme des minutes.",l:"spp"},
{q:"1 h 45 min, c'est combien de minutes ?",o:["105 min","145 min","95 min","115 min"],e:"60 + 45 = 105 min.",l:"spp"},
{q:"Départ à 23 h 40, l'intervention dure 2 h 35. Heure de fin ?",o:["2 h 15","1 h 15","3 h 15","2 h 05"],e:"23 h 40 + 2 h 35 = 25 h 75 = 26 h 15, soit 2 h 15 le lendemain.",l:"spp"},
{q:"Aire d'un local rectangulaire de 12 m sur 8 m ?",o:["96 m²","40 m²","80 m²","192 m²"],e:"Aire = longueur × largeur = 12 × 8 = 96 m².",l:"spp"},
{q:"Volume d'une pièce de 5 m × 4 m × 2,5 m de haut ?",o:["50 m³","11,5 m³","45 m³","500 m³"],e:"Volume = 5 × 4 × 2,5 = 50 m³.",l:"spp"},
{q:"Périmètre d'un carré de 7 m de côté ?",o:["28 m","49 m","14 m","21 m"],e:"Périmètre = 4 × côté = 28 m (49 m² est son aire).",l:"spp"},
{q:"Aire d'un cercle de 10 m de rayon (π ≈ 3,14) ?",o:["314 m²","62,8 m²","31,4 m²","628 m²"],e:"Aire = π × r² = 3,14 × 100 = 314 m² (62,8 m est le périmètre).",l:"spp"},
{q:"3 bouteilles coûtent 450 €. Combien coûtent 5 bouteilles ?",o:["750 €","600 €","900 €","650 €"],e:"Règle de trois : 450 ÷ 3 = 150 € l'unité, × 5 = 750 €.",l:"spp"},
{q:"Moyenne de 12, 15, 9 et 14 ?",o:["12,5","12","13","11,5"],e:"(12 + 15 + 9 + 14) ÷ 4 = 50 ÷ 4 = 12,5.",l:"spp"},
{q:"Combien font les 3/4 de 120 ?",o:["90","80","40","100"],e:"120 ÷ 4 = 30, × 3 = 90.",l:"spp"},
{q:"Quelle fraction est égale à 0,25 ?",o:["1/4","2/5","1/25","25/10"],e:"1 ÷ 4 = 0,25.",l:"spp"},
{q:"Combien font 1,2 × 0,5 ?",o:["0,6","6","0,06","1,7"],e:"Multiplier par 0,5 revient à diviser par 2.",l:"spp"},
{q:"Résous : 3x + 5 = 20",o:["x = 5","x = 15","x = 7","x = 3"],e:"3x = 20 − 5 = 15, donc x = 15 ÷ 3 = 5.",l:"spp"},
{q:"Sur une carte au 1/25 000, 4 cm représentent :",o:["1 km","10 km","100 m","4 km"],e:"4 × 25 000 = 100 000 cm = 1 000 m = 1 km.",l:"spp"},
{q:"2,5 km, c'est :",o:["2 500 m","250 m","25 000 m","25 m"],e:"1 km = 1 000 m.",l:"spp"}
]
};

